'use strict';
/* Guía de consulta (español) — parte 2: Recursos narrativos, Técnicas narrativas, Métodos narrativos y Estilos narrativos.
   Mismo formato que las demás partes: SUPPORT.push({ key, name, kicker, intro, groups:[ { name, items:[...] } ] }).
   Campos de cada ficha: n (nombre), a (otros nombres), d (definición), u (cómo usarlo), c (cuidado), x (ejemplos),
   t (cómo aplicarlo en la herramienta), s (fichas relacionadas). Títulos de obras en *cursiva*; comillas angulares « »,
   y dentro “ ” y ‘ ’, según la *Ortografía de la lengua española* (RAE y ASALE, 2010). Norma de España, con las
   variantes de América cuando importan. Los ejemplos sin autor son frases inventadas para ilustrar. */

/* ============ RECURSOS NARRATIVOS ============ */
SUPPORT.push({ key:'recursos', name:'Recursos narrativos', kicker:'Recurso',
  intro:'Los dispositivos que hacen funcionar la trama: qué se pone en la historia y en qué orden se revela para crear expectación, sorpresa y sentido. Si las figuras retóricas trabajan la frase, estos recursos trabajan la historia: el tiempo, la información que tiene el lector, los motores del conflicto y las funciones de los personajes.',
  groups:[
  { name:'Tiempo y orden', items:[
    { n:'Analepsis', a:'Flashback · retrospección · vuelta atrás',
      d:'Salto hacia el pasado: la narración interrumpe el presente de la historia para contar hechos anteriores.',
      u:'Úsela cuando el pasado se vuelve necesario para entender el presente, y mejor cuando el lector ya quiere saberlo. Entre y salga con un disparador concreto (un olor, un objeto, una frase). Puede ser una escena completa, un párrafo o una sola frase de recuerdo. Marque bien el cambio de tiempo verbal al entrar (pluscuamperfecto) y vuelva al pretérito en cuanto el lector esté situado.',
      c:'Una analepsis en las primeras páginas frena el arranque. Si el pasado interesa más que el presente, quizá la historia debería empezar allí. Abusar del pluscuamperfecto («había ido», «había dicho») vuelve pesada la vuelta atrás.',
      x:['*Pedro Páramo* (Rulfo): el presente de Juan Preciado en Comala se mezcla con los recuerdos de Susana San Juan y de Pedro Páramo, sin avisos.', '*La Regenta* (Clarín): tras presentar a Ana Ozores en Vetusta, el narrador retrocede a su infancia y a la «aventura» de la barca.', '*Cumbres borrascosas*: casi toda la novela es el relato retrospectivo de Nelly Dean.', '*El padrino II*: la juventud de Vito en paralelo al presente de Michael.'],
      t:'Cada Escena tiene dos posiciones: el orden narrativo (dónde se cuenta, la línea blanca del tablero) y el orden cronológico (cuándo ocurre, las líneas de color de cada Arco narrativo). Una analepsis es una Escena tardía en el tablero y temprana en la cronología.',
      s:['Prolepsis', 'In medias res', 'Narración no lineal', 'Tiempos verbales de la narración'] },
    { n:'Prolepsis', a:'Flashforward · anticipación',
      d:'Salto hacia el futuro: la narración adelanta hechos que solo ocurrirán más tarde.',
      u:'Cambia la pregunta «¿qué va a pasar?» por «¿cómo va a pasar?». Basta una frase («Sería la última vez que la vería»). Las profecías, los sueños y los presagios son prolepsis dentro de la propia historia.',
      c:'Anticipar demasiado quita tensión a las escenas que siguen; anticipar lo poco importante es ruido.',
      x:['*Cien años de soledad* empieza con el coronel Aureliano Buendía frente al pelotón de fusilamiento, «muchos años después».', '*Crónica de una muerte anunciada* (García Márquez): la muerte de Santiago Nasar se anuncia en la primera frase.', '*El túnel* (Sábato): Castel confiesa en la primera línea que mató a María Iribarne.', 'Las profecías de las brujas en *Macbeth*.'],
      s:['Analepsis', 'Presagio', 'Ironía dramática', 'Tiempo de la narración'] },
    { n:'In medias res', a:'Empezar en mitad de la acción',
      d:'Abrir el relato con la acción ya en marcha y dejar los antecedentes para más adelante. Lo contrario es empezar *ab ovo*, por el principio de todo.',
      u:'Abra con una escena que tenga movimiento y una pregunta, lo más cerca posible del incidente incitador. Dé solo el contexto imprescindible y reparta el resto después, en analepsis o en diálogo.',
      c:'Empezar con acción pura, sin un personaje que le importe al lector, es solo ruido; y volver al pasado en el segundo capítulo puede decepcionar.',
      x:['La *Odisea* empieza con Ulises lejos de casa desde hace años; la *Ilíada*, en el décimo y último año de la guerra.', '*La metamorfosis* (Kafka): Gregor Samsa ya despierta transformado.', '«La noche boca arriba» (Cortázar): el protagonista ya va en moto, camino del accidente.'],
      s:['Analepsis', 'Incidente incitador', 'Entrar tarde, salir pronto', 'Exposición dosificada'] },
    { n:'Carrera contrarreloj', a:'Cuenta atrás · plazo · reloj que corre · ticking clock',
      d:'Un límite de tiempo que el lector conoce, pasado el cual ocurrirá algo irreversible.',
      u:'Da urgencia a cualquier objetivo y obliga a los personajes a actuar y a equivocarse. El plazo debe ser concreto (la medianoche, la boda, la marea, el oxígeno) y puede acortarse a mitad de camino para apretar la tensión.',
      c:'Un plazo que se olvida o que se alarga sin consecuencias se vuelve en contra: el lector deja de creer en él.',
      x:['*La vuelta al mundo en ochenta días* (Julio Verne).', 'La medianoche de Cenicienta.', '*Solo ante el peligro* (en América, *A la hora señalada*): el duelo fijado para el mediodía.', '*Crónica de una muerte anunciada*: todo el pueblo sabe la hora, menos la víctima.'],
      s:['Lo que está en juego', 'Suspense y sorpresa', 'Ritmo narrativo'] },
    { n:'Estructura circular', a:'Relato circular · composición en anillo',
      d:'El final vuelve al punto de partida (el mismo lugar, imagen, frase o situación), pero con el sentido transformado por lo que ha ocurrido entre medias.',
      u:'Muestre la misma imagen al principio y al final: la diferencia entre ambas mide el arco del personaje. O no cambie nada, y la vuelta se convierte en condena.',
      c:'Si el regreso no significa nada nuevo, el círculo parece un truco de simetría.',
      x:['*El hobbit*, con su subtítulo «Historia de una ida y una vuelta».', '*Cien años de soledad*: el final cumple lo que ya contenían los pergaminos de Melquíades.', '*Finnegans Wake* (Joyce): la última frase continúa en la primera.', '«Continuidad de los parques» (Cortázar): el relato termina donde empezaba la lectura.'],
      s:['Relato enmarcado', 'Motivo recurrente', 'Arco de personaje'] }
  ]},
  { name:'Información, suspense y revelación', items:[
    { n:'Presagio', a:'Prefiguración · anticipación sutil · foreshadowing · indicio',
      d:'Señal discreta que anuncia lo que vendrá: un detalle, una frase, una imagen, un sueño, un incidente menor que ensaya el mayor.',
      u:'Lo ideal es que pase inadvertido en la primera lectura y parezca inevitable en la segunda. Escóndalo en una enumeración, en una escena de humor o de acción. Escriba primero el desenlace y vuelva atrás para sembrarlo.',
      c:'Demasiado evidente, estropea la sorpresa; inexistente, hace que el desenlace parezca arbitrario.',
      x:['«El almohadón de plumas» (Quiroga): la palidez creciente de Alicia y las manchas en la funda preparan el horror del final.', '*Crónica de una muerte anunciada*: los sueños de árboles y pájaros de Santiago Nasar.', '*Romeo y Julieta*: el prólogo y los presentimientos de los amantes.', '*De ratones y hombres* (Steinbeck): la muerte del perro viejo ensaya el final.'],
      t:'Asocie una Nota a las dos Escenas (la que siembra y la que cosecha) para no perder de vista ningún presagio.',
      s:['Siembra y cosecha', 'El arma de Chéjov', 'Prolepsis', 'Pista falsa'] },
    { n:'El arma de Chéjov', a:'La escopeta de Chéjov · principio de economía',
      d:'Principio de economía: todo lo que la historia pone de relieve debe tener una función. Si en el primer acto hay un fusil colgado en la pared, en el tercero tiene que dispararse.',
      u:'Léalo en los dos sentidos: elimine lo que no va a servir y presente con antelación todo lo que será decisivo al final (el objeto, la habilidad, la debilidad).',
      c:'No significa que cada detalle tenga que ser una pista: el decorado necesita textura. Se aplica a lo que el texto subraya.',
      x:['En *Tío Vania*, del propio Chéjov, la pistola se dispara... y falla.', 'El giratiempo en *Harry Potter*: presentado como curiosidad, decisivo después.', 'La plancha de estufa bajo el poncho en *Regreso al futuro III*, que ya se había visto antes en una película de la televisión.'],
      s:['Siembra y cosecha', 'Presagio', 'Deus ex machina'] },
    { n:'Siembra y cosecha', a:'Planteamiento y pago · setup y payoff · preparación y recompensa',
      d:'Pareja de momentos: algo se establece pronto (un objeto, una frase, una regla, una promesa) y más tarde vuelve con consecuencias. Es el mecanismo general del que el presagio y el arma de Chéjov son casos particulares.',
      u:'Siembre tres veces lo esencial, en contextos distintos; coseche cuando el lector casi lo ha olvidado. Toda promesa hecha al lector (un misterio, una amenaza, un beso aplazado) es una deuda que hay que pagar.',
      c:'Cosechas sin siembra suenan a trampa; siembras sin cosecha, a cabos sueltos.',
      x:['*Regreso al futuro*: el folleto sobre el rayo en la torre del reloj.', '«La muerte y la brújula» (Borges): cada pista sembrada por el asesino conduce a Lönnrot a la trampa final.', 'En *Harry Potter*, la cicatriz, la serpiente, el guardapelo: todo vuelve.'],
      t:'Asocie la misma Referencia o Nota a las Escenas de siembra y de cosecha.',
      s:['El arma de Chéjov', 'Presagio', 'Motivo recurrente', 'Revisión por capas'] },
    { n:'Pista falsa', a:'Red herring · arenque rojo · señuelo',
      d:'Elemento que desvía deliberadamente la atención y las sospechas del lector hacia una dirección equivocada.',
      u:'Tiene que ser verosímil y tener su propia explicación al final (el sospechoso ocultaba otra cosa). La mejor esconde la pista verdadera, presentada en el mismo momento y con menos realce.',
      c:'Si nunca se explica, es un cabo suelto; si solo hay pistas falsas, el lector se siente estafado.',
      x:['Snape en *Harry Potter y la piedra filosofal*.', '*El club Dumas* (Pérez-Reverte): la pista del manuscrito de Dumas lleva al lector por un camino que no es el del libro de las Nueve Puertas.', '*El sabueso de los Baskerville* (Conan Doyle): el preso fugado en el páramo.'],
      s:['Presagio', 'Giro argumental', 'Narrador no fiable'] },
    { n:'Suspense y sorpresa', a:'Suspenso (en América) · la bomba bajo la mesa (Hitchcock)',
      d:'Sorpresa: el lector no sabe lo que viene y lo pilla desprevenido; quince segundos de choque. Suspense: el lector sabe que hay una bomba bajo la mesa y los personajes no; quince minutos de angustia.',
      u:'Para crear suspense, dé información al lector en vez de esconderla, haga posibles las dos salidas y aplace el desenlace. El suspense necesita que al lector le importe quien está en peligro.',
      c:'Las sorpresas en serie cansan; el suspense sin resolución irrita.',
      x:['*Psicosis* (Hitchcock): la sorpresa de la ducha; después, el suspense cada vez que alguien se acerca a la casa.', '*Tiburón*: el público ve la aleta antes que los bañistas.', 'La escena inicial de *Malditos bastardos* (Tarantino): sabemos quién se esconde bajo el suelo.'],
      s:['Ironía dramática', 'Carrera contrarreloj', 'Pregunta dramática', 'Gancho'] },
    { n:'Ironía dramática', a:'Ironía trágica',
      d:'El lector sabe algo que uno o varios personajes ignoran. Cada frase y cada gesto adquieren un segundo sentido.',
      u:'Es fuente de tensión (el peligro que solo vemos nosotros), de comedia (el equívoco) y de tragedia (el error que solo nosotros entendemos). Funciona muy bien con varios puntos de vista: lo que sabe un Personaje POV lo ignora el siguiente.',
      c:'Si el lector va demasiado por delante y los personajes tardan mucho en enterarse, la ironía se vuelve exasperación.',
      x:['*Edipo rey* (Sófocles): Edipo busca al asesino que es él mismo.', '*Romeo y Julieta*: sabemos que Julieta solo duerme.', '*Crónica de una muerte anunciada*: todos saben que van a matar a Santiago Nasar, salvo él.', '*El sí de las niñas* (Moratín): el público conoce el amor de Paquita antes que don Diego.'],
      t:'Con varios Arcos narrativos y Personajes POV, el tablero muestra lo que cada hilo ya ha revelado en cada punto del orden narrativo.',
      s:['Suspense y sorpresa', 'Ironía', 'Anagnórisis y peripecia'] },
    { n:'Pregunta dramática', a:'Pregunta central · cuestión dramática',
      d:'La pregunta que la historia plantea al principio y que solo responde en el clímax: ¿lo conseguirá el héroe?, ¿quién mató?, ¿acabarán juntos? Cada escena plantea, además, preguntas menores.',
      u:'Formule la pregunta central en una frase y compruebe que el clímax la responde. Para mantener la lectura, abra una pregunta nueva antes de cerrar la anterior.',
      c:'Un clímax que responde a otra pregunta distinta de la planteada deja al lector con la sensación de que le han cambiado el libro.',
      x:['«¿Quién mató a Roger Ackroyd?»', '«¿Conseguirá Ulises volver a Ítaca, y qué encontrará allí?»', '«¿Vencerán Elizabeth y Darcy el orgullo y el prejuicio?»'],
      s:['Gancho', 'Clímax', 'Premisa y logline'] },
    { n:'Gancho', a:'Cliffhanger (al final del capítulo) · anzuelo (en el arranque)',
      d:'Elemento que atrapa al lector y le obliga a seguir. En el arranque: una frase, una voz o una situación intrigante. Al final del capítulo: un corte en el momento de máxima tensión, una revelación o una pregunta nueva.',
      u:'Corte el capítulo antes de la respuesta, no después. Varíe los tipos (peligro, revelación, decisión, llegada de alguien). Con varios hilos, cambiar de hilo tras un gancho duplica el efecto.',
      c:'Si todos los capítulos acaban con alguien desmayándose, el truco se ve; y un gancho resuelto con una trivialidad es un engaño.',
      x:['Sherezade en *Las mil y una noches*: interrumpe la historia al amanecer para sobrevivir un día más.', 'La novela por entregas del siglo XIX (Dickens, Dumas, Galdós, Fernández y González) vivía del «continuará».', '*La sombra del viento* (Ruiz Zafón): capítulos que se cierran con una revelación o una amenaza.'],
      s:['Capítulos cortos y ganchos', 'Suspense y sorpresa', 'Montaje paralelo', 'Pregunta dramática'] },
    { n:'Giro argumental', a:'Giro de guion · vuelta de tuerca · plot twist',
      d:'Cambio brusco e inesperado del rumbo de la historia o de la manera en que la entendemos.',
      u:'El buen giro es sorprendente e inevitable: sorprende en el momento y, al mirar atrás, todo estaba ahí. Obliga a reinterpretar lo leído y sube lo que está en juego. Constrúyalo desde el final y siembre las pistas a la vista.',
      c:'El giro que contradice lo mostrado, o que anula lo que el lector ha vivido («todo era un sueño»), se percibe como una traición.',
      x:['*El asesinato de Roger Ackroyd* (Agatha Christie).', '«La noche boca arriba» (Cortázar): el sueño y la vigilia se invierten en la última línea.', '*Los otros* (Amenábar); *El sexto sentido*; *El club de la lucha*.', '*El imperio contraataca*: «Yo soy tu padre».'],
      s:['Anagnórisis y peripecia', 'Presagio', 'Pista falsa', 'Narrador no fiable', 'Punto medio'] },
    { n:'Anagnórisis y peripecia', a:'Reconocimiento e inversión (Aristóteles)',
      d:'Peripecia: inversión súbita de la situación, de la dicha a la desgracia o al revés. Anagnórisis: paso de la ignorancia al conocimiento; el personaje descubre una identidad o una verdad. Según la *Poética*, el efecto es mayor cuando ambas coinciden.',
      u:'Haga de la revelación un acto que lo cambia todo: el reconocimiento debe obligar a una decisión. Puede ser de otra persona (quién es) o de uno mismo (quién soy, qué he hecho).',
      c:'Una anagnórisis que no tiene consecuencias es solo un dato. Y si el lector la adivina cien páginas antes, la escena llega tarde.',
      x:['*Edipo rey*: el mensajero que viene a tranquilizar a Edipo le revela su origen y lo destruye.', '*La vida es sueño* (Calderón): Segismundo comprende quién es y cambia de conducta.', '«Emma Zunz» (Borges): el lector reconoce al final el sentido de toda la venganza.', 'El regreso de Ulises, reconocido por la cicatriz.'],
      s:['Giro argumental', 'Ironía dramática', 'Clímax', 'Defecto trágico'] }
  ]},
  { name:'Motores de la trama', items:[
    { n:'Incidente incitador', a:'Detonante · catalizador · inciting incident',
      d:'El suceso que rompe el equilibrio inicial y pone la historia en marcha: sin él, la vida del personaje seguiría igual.',
      u:'Debe ocurrir pronto, en escena (no en resumen), afectar al protagonista y plantear la pregunta dramática. Puede ser una oportunidad, una pérdida, un encuentro, una carta, un cadáver.',
      c:'Un detonante que tarda cincuenta páginas en llegar, sin otra tensión que lo sostenga, hace que el lector abandone antes.',
      x:['La llegada de Bingley al vecindario en *Orgullo y prejuicio*.', 'La carta de Hogwarts.', 'Katniss se ofrece voluntaria en lugar de su hermana en *Los juegos del hambre*.', 'Don Quijote lee tantos libros de caballerías que decide hacerse caballero andante.'],
      s:['Estructura en tres actos', 'Pregunta dramática', 'Punto de no retorno', 'In medias res'] },
    { n:'Lo que está en juego', a:'Las apuestas · stakes',
      d:'Lo que el personaje gana si lo consigue y, sobre todo, lo que pierde si fracasa.',
      u:'Hágalo claro, personal y creciente. Lo exterior (la vida, el reino, el empleo) pesa más cuando se une a lo interior (la identidad, el amor, la culpa). Muestre pronto aquello que puede perderse, para que el lector le coja cariño.',
      c:'«El fin del mundo» es una apuesta abstracta: la muerte de una persona que conocemos pesa más que la de un planeta.',
      x:['*Los juegos del hambre*: la propia vida y la de la hermana.', '*El señor de los anillos*: la Tierra Media, pero también la Comarca y el alma de Frodo.', '*Lo que queda del día* (Ishiguro): solo una vida desperdiciada, y basta.', '*El coronel no tiene quien le escriba*: el gallo, la dignidad y el hambre.'],
      s:['Carrera contrarreloj', 'Dilema', 'Obstáculos y complicaciones'] },
    { n:'Obstáculos y complicaciones', a:'Conflicto · escalada',
      d:'Todo lo que se opone al deseo del personaje: un antagonista, el medio, la sociedad, la naturaleza, el destino o él mismo. La complicación es el obstáculo que, además de frenar, empeora o altera la situación.',
      u:'Sin oposición no hay historia. Haga que los obstáculos crezcan en dificultad y varíen de naturaleza (exterior, de relación, interior). El mejor obstáculo nace del propio plan del personaje o del deseo legítimo de otro.',
      c:'Obstáculos que se superan sin coste, o que se repiten iguales, no hacen avanzar nada.',
      x:['Tipos de conflicto: personaje contra personaje (*Los miserables*: Valjean y Javert), contra la sociedad (*1984*), contra la naturaleza (*El viejo y el mar*), contra sí mismo (*Crimen y castigo*), contra el destino (*Edipo rey*).', '*La vorágine* (Rivera): la selva como antagonista.'],
      s:['Ciclos de intento y fracaso', 'Antagonista', 'Dilema', 'Curva de Fichte'] },
    { n:'Dilema', a:'Elección imposible',
      d:'Elección entre dos opciones incompatibles, ambas con coste: dos bienes que se excluyen o dos males inevitables.',
      u:'En la elección bajo presión es donde el personaje se revela. Ponga el dilema en el clímax y haga que la decisión cueste algo que conocemos.',
      c:'Si una de las opciones es claramente mejor, no es un dilema: es solo un obstáculo.',
      x:['*La decisión de Sophie* (William Styron).', 'Antígona: obedecer la ley de la ciudad o enterrar al hermano.', '*La casa de Bernarda Alba*: Adela entre la obediencia y el deseo.', 'Frodo en el Monte del Destino.'],
      s:['Lo que está en juego', 'Clímax', 'Arco de personaje'] },
    { n:'MacGuffin', a:'Término popularizado por Hitchcock',
      d:'El objeto u objetivo que todos los personajes persiguen y que pone la trama en movimiento, pero cuya naturaleza exacta importa poco al público.',
      u:'Da a los personajes una razón para cruzarse y chocar. El interés está en lo que hacen para conseguirlo. Se gana mucho si, además, tiene valor simbólico o emocional.',
      c:'Si el lector exige saber qué es y nunca se lo explican, o si la explicación final decepciona, el MacGuffin se convierte en promesa incumplida.',
      x:['La estatuilla de *El halcón maltés* (Dashiell Hammett).', 'El maletín de *Pulp Fiction*, cuyo contenido nunca vemos.', 'Los planos de la Estrella de la Muerte en *La guerra de las galaxias*.', 'El libro de las Nueve Puertas en *El club Dumas*; el Santo Grial en los relatos artúricos.'],
      s:['Pregunta dramática', 'Símbolo', 'Lo que está en juego'] },
    { n:'Punto de no retorno', a:'Cruce del umbral · primer punto de giro · primer nudo',
      d:'El momento en que el personaje toma una decisión o sufre un suceso que hace imposible volver a su vida anterior. Suele marcar la entrada en el segundo acto.',
      u:'Debe ser una elección (aunque forzada), no un azar. Queme el puente: la casa arde, el secreto se dice, el barco zarpa.',
      c:'Si el personaje podría volver atrás sin coste, el umbral es de cartón y el segundo acto pierde presión. Tampoco lo retrase demasiado: un primer acto eterno agota al lector.',
      x:['Bilbo sale corriendo de casa sin pañuelo.', 'Raskólnikov comete el crimen.', 'Don Quijote sale por primera vez de su aldea, de madrugada y sin avisar a nadie.', 'En *Matrix*, Neo elige la pastilla roja.'],
      s:['Incidente incitador', 'Estructura en tres actos', 'El viaje del héroe'] },
    { n:'Punto medio', a:'Midpoint · giro central',
      d:'El suceso en mitad de la historia que cambia las reglas del juego: una revelación, una falsa victoria o una falsa derrota, que hace que el protagonista pase de reaccionar a actuar.',
      u:'Combate el «centro pantanoso» de las novelas. Suba lo que está en juego, revele algo que cambie el sentido del objetivo o dé una victoria que lleve un precio.',
      c:'Un punto medio que no cambia nada (solo una escena de acción más) deja el segundo acto igual de plano.',
      x:['*Perdida* (Gillian Flynn): el cambio de narradora a mitad del libro.', '*Orgullo y prejuicio*: la primera declaración de Darcy y la carta que la sigue.', '*Titanic*: el iceberg.'],
      s:['Estructura en tres actos', 'Save the Cat', 'Giro argumental'] },
    { n:'Todo está perdido', a:'La noche oscura del alma · crisis',
      d:'El punto más bajo, antes del clímax: el plan ha fallado, el mentor ha muerto, los aliados se han alejado y el personaje tiene que enfrentarse a su defecto.',
      u:'La derrota debe ser consecuencia de los errores del personaje y obligarle a cambiar (o a negarse a cambiar, en la tragedia). Cuanto más hondo el pozo, mayor el efecto del clímax.',
      c:'Una crisis provocada solo por el azar, sin culpa del protagonista, no enseña nada y el clímax pierde sentido.',
      x:['La muerte de Gandalf en Moria; la de Obi-Wan; la de Dumbledore.', 'Elizabeth convencida de que la fuga de Lydia la ha separado de Darcy para siempre.', 'Don Quijote vencido por el Caballero de la Blanca Luna en la playa de Barcelona.'],
      s:['Clímax', 'Save the Cat', 'Arco de personaje', 'Mentor'] },
    { n:'Clímax', a:'Culminación · momento culminante',
      d:'El momento de máxima tensión, en que se decide el conflicto central y la pregunta dramática recibe respuesta.',
      u:'El protagonista debe estar presente y decidir con sus propios actos, usando lo que ha aprendido. El clímax exterior (la batalla) y el interior (la elección) deben coincidir. Todo lo sembrado se cosecha aquí.',
      c:'Un clímax resuelto por otro personaje, por el azar o por una regla nueva quita el mérito al protagonista.',
      x:['La destrucción del Anillo en el Monte del Destino.', 'El duelo final de *Hamlet*.', 'La segunda declaración de Darcy.', 'El asesinato de Santiago Nasar en la puerta de su casa, contado al fin en escena.'],
      s:['Dilema', 'Desenlace', 'Deus ex machina', 'Pirámide de Freytag'] },
    { n:'Desenlace', a:'Resolución · epílogo',
      d:'Lo que viene después del clímax: las consecuencias, los hilos que se atan, el nuevo equilibrio. El epílogo es un desenlace separado de la acción por un salto temporal.',
      u:'Muestre el mundo cambiado y el precio de la victoria. Sea breve: la tensión ha terminado. Los finales abiertos también son desenlaces: responden a la pregunta central y dejan abierto lo que vendrá después.',
      c:'Un desenlace que se alarga atando hilos menores diluye el clímax; uno que no ata nada parece un libro inacabado.',
      x:['La vuelta de don Quijote a su aldea, su enfermedad y su recuperación del juicio.', 'El regreso a la Comarca en *El señor de los anillos*.', 'Final abierto: *El gran Gatsby*; *La carretera* (McCarthy).'],
      s:['Clímax', 'Estructura circular', 'Pirámide de Freytag', 'Final abierto'] },
    { n:'Deus ex machina', a:'«El dios que baja de la máquina»',
      d:'Solución repentina y externa para un problema sin salida: un personaje, una fuerza o una coincidencia que no se ha preparado y lo resuelve todo. El nombre viene del teatro griego, en el que un dios bajaba al escenario con una grúa.',
      u:'Por regla general, evítelo: la solución debe nacer de los personajes y de lo sembrado. La coincidencia puede meter a los personajes en apuros; no debería sacarlos de ellos. Se usa a propósito en la comedia, la sátira y la parodia.',
      c:'Un rescate a última hora sin preparación invalida todo el esfuerzo del protagonista y el lector lo nota.',
      x:['*Medea* (Eurípides): el carro del Sol se lleva a Medea.', 'Las águilas en *El hobbit* y *El señor de los anillos*, tema de discusión eterna.', 'La intervención del rey al final de *Tartufo* (Molière).', '*La guerra de los mundos* (H. G. Wells): las bacterias, aunque ahí ese es justamente el tema.'],
      s:['El arma de Chéjov', 'Siembra y cosecha', 'Clímax', 'Verosimilitud'] },
    { n:'Final abierto', a:'Final ambiguo · final suspendido',
      d:'Desenlace que responde a la pregunta central de la historia pero deja sin resolver una parte de su sentido (qué pasará después, qué era verdad), para que el lector lo complete.',
      u:'Cierre el conflicto dramático y deje abierta la interpretación, no al revés. Funciona cuando la duda final es la pregunta temática del libro. Siembre las dos lecturas con la misma lealtad.',
      c:'Un final abierto por falta de decisión del autor se nota: si la trama queda a medias, el lector se siente abandonado, no invitado.',
      x:['*Rayuela* (Cortázar): Oliveira en la ventana; el lector decide si salta.', '«Casa tomada» (Cortázar): nunca sabemos quién ocupa la casa.', '*La carretera* (McCarthy); *El gran Gatsby*.', '*Nada* (Laforet): Andrea se marcha de Barcelona sin que sepamos qué la espera.'],
      s:['Desenlace', 'El tema como pregunta', 'Pregunta dramática'] }
  ]},
  { name:'Personajes como recurso', items:[
    { n:'Arco de personaje', a:'Arco de transformación',
      d:'La transformación interior de un personaje a lo largo de la historia. Arco positivo: vence un defecto o una creencia equivocada. Arco negativo: cede a ella (caída, corrupción, desengaño). Arco plano: no cambia; cambia el mundo a su alrededor.',
      u:'Defina lo que el personaje quiere (objetivo exterior), lo que necesita (verdad interior) y la mentira en la que cree. La trama es la serie de presiones que le obliga a elegir entre ambas cosas.',
      c:'Un cambio que ocurre de golpe en la última escena, sin pasos intermedios, no es un arco: es un milagro.',
      x:['Positivo: Scrooge en *Cuento de Navidad*; Elizabeth Bennet.', 'Negativo: Michael Corleone; Macbeth; Walter White.', 'Plano: Sherlock Holmes; James Bond.', 'Don Quijote y Sancho: la «quijotización» de Sancho y la «sanchificación» de don Quijote (Salvador de Madariaga).'],
      t:'En la ficha del Personaje se ven las Escenas en las que aparece, en el orden en que se cuentan: es el esqueleto del arco.',
      s:['Deseo y necesidad', 'Defecto trágico', 'Todo está perdido', 'El viaje del héroe'] },
    { n:'Defecto trágico', a:'Hamartía · error trágico · herida y mentira',
      d:'El error de juicio o rasgo de carácter que conduce al héroe a la caída (en la tragedia) o que tiene que vencer (en las demás historias). La escritura actual habla de la «herida» (lo que le pasó) y de la «mentira» (lo que pasó a creer por eso).',
      u:'El defecto debe ser el reverso de una virtud (el valor que es temeridad, la lealtad que es ceguera) y debe causar los problemas de la trama.',
      c:'Un defecto decorativo (es «un poco impaciente») que nunca causa nada no sirve para la trama.',
      x:['La soberbia (hybris) de Edipo.', 'La ambición de Macbeth; los celos de Otelo; la indecisión de Hamlet.', 'El orgullo de Darcy y el prejuicio de Elizabeth.', 'La honra de don Gutierre en *El médico de su honra* (Calderón).'],
      s:['Arco de personaje', 'Anagnórisis y peripecia', 'Deseo y necesidad'] },
    { n:'Antagonista', a:'Oponente · villano',
      d:'La fuerza que se opone al protagonista. No tiene por qué ser un villano: puede ser un rival con un objetivo legítimo, una institución, la naturaleza o el propio protagonista.',
      u:'El mejor antagonista quiere algo comprensible, es más fuerte que el héroe al principio y le ataca justo en su debilidad. Cada antagonista es el héroe de su propia historia.',
      c:'El villano que es malo «porque sí» no da miedo.',
      x:['Javert en *Los miserables*: la ley sin misericordia.', 'Yago en *Otelo*.', 'El Gran Hermano en *1984*.', 'Bernarda Alba, que convierte la casa en cárcel.'],
      s:['Obstáculos y complicaciones', 'Personaje contraste', 'Antihéroe'] },
    { n:'Antihéroe', a:'Héroe sin cualidades heroicas',
      d:'Protagonista sin las cualidades tradicionales del héroe: cobarde, egoísta, amoral, fracasado o simplemente vulgar.',
      u:'El lector no necesita que le caiga bien; necesita entenderlo y no poder apartar la mirada. Dele una competencia, un código, humor o una vulnerabilidad.',
      c:'Un antihéroe sin ninguna dimensión que lo haga interesante no es audaz: es aburrido.',
      x:['Lázaro de Tormes y los demás pícaros; don Quijote.', 'Raskólnikov en *Crimen y castigo*.', 'Meursault en *El extranjero*.', 'Pascual Duarte (Cela); Tom Ripley (Patricia Highsmith).'],
      s:['Antagonista', 'Narrador no fiable', 'Arco de personaje', 'Novela picaresca'] },
    { n:'Personaje contraste', a:'Foil · personaje espejo · contrafigura',
      d:'Personaje cuyas características contrastan con las de otro (por lo general, el protagonista) y las hacen más visibles.',
      u:'Ponga a la pareja ante la misma situación con respuestas opuestas. El contraste muestra lo que el protagonista podría haber sido.',
      c:'Si el contraste es puramente esquemático (uno todo luz, otro todo sombra), ambos se vuelven caricaturas.',
      x:['Don Quijote y Sancho Panza.', 'Fortunata y Jacinta (Galdós).', 'Sherlock Holmes y Watson.', 'Harry Potter y Draco Malfoy.'],
      s:['Antítesis', 'Subtrama', 'Confidente', 'El doble'] },
    { n:'Confidente', a:'Personaje confidente',
      d:'Personaje a quien el protagonista confía pensamientos y planes y, a través de él, al lector.',
      u:'Convierte el monólogo en diálogo y la exposición en escena. Debe tener vida y opiniones propias (discrepar es más útil que asentir).',
      c:'El confidente que solo hace preguntas es un micrófono con piernas.',
      x:['Horacio en *Hamlet*.', 'Watson.', 'Sancho para don Quijote, que además le lleva la contraria.', 'Celestina no lo es: sabe todos los secretos y trabaja para sí misma; por eso la obra funciona.'],
      s:['Personaje contraste', 'Exposición dosificada', 'Estilo directo'] },
    { n:'Mentor', a:'Maestro · guía',
      d:'Figura de más edad o sabiduría que prepara al héroe, le da un don (saber, objeto, confianza) y, a menudo, desaparece antes de la prueba final.',
      u:'El mentor tiene que salir de escena para que el héroe demuestre lo aprendido. Dele defectos, secretos o un pasado que complique la lección.',
      c:'El mentor que lo sabe todo y resuelve los problemas deja al héroe sin nada que hacer.',
      x:['Gandalf; Dumbledore; Obi-Wan Kenobi.', 'Méntor (Atenea disfrazada) en la *Odisea*, origen de la palabra.', 'Patronio, que aconseja al conde Lucanor con un cuento en cada capítulo.'],
      s:['El viaje del héroe', 'Todo está perdido', 'Personaje tipo'] },
    { n:'Personaje tipo', a:'Tipo social · personaje plano y redondo (E. M. Forster) · arquetipo',
      d:'El personaje tipo representa una clase, un oficio o un vicio, con pocos rasgos fijos. Forster distingue los personajes planos (una sola idea, no cambian) de los redondos (complejos, capaces de sorprender de modo convincente).',
      u:'Los planos son útiles: se reconocen enseguida, sirven a la sátira y pueblan el fondo. Los principales deben ser redondos: deles una contradicción.',
      c:'Un protagonista plano no aguanta una novela; un secundario demasiado redondo puede robarle el libro.',
      x:['La Celestina, el escudero hidalgo y pobre del *Lazarillo*, el clérigo avaro.', 'El figurón y el gracioso del teatro del Siglo de Oro.', 'Dickens: Mr. Micawber, siempre esperando a que «salga algo».'],
      s:['Caracterización directa e indirecta', 'Alegoría', "Idiolecto y marcas de oralidad"] },
    { n:'El doble', a:'Doppelgänger · sosia · alter ego',
      d:'Personaje que es reflejo, réplica o sombra de otro: un gemelo, un desconocido idéntico, una segunda personalidad. Encarna lo que el protagonista reprime, teme o desea.',
      u:'Úselo para dar cuerpo a un conflicto interior: el doble hace lo que el protagonista no se atreve a hacer. Funciona en lo fantástico, en el thriller psicológico y en la novela de identidad.',
      c:'Si el doble no revela nada del original, es un truco de magia sin sentido. Y el «era él mismo» final está muy gastado.',
      x:['*El extraño caso del doctor Jekyll y míster Hyde* (Stevenson).', '«William Wilson» (Poe); *El doble* (Dostoievski).', '«El otro» (Borges): el viejo Borges se encuentra con el joven en un banco.', '*Abel Sánchez* (Unamuno): Joaquín y Abel, el envidioso y su sombra.'],
      s:['Personaje contraste', 'Lo fantástico', 'Antagonista'] },
    { n:'Subtrama', a:'Trama secundaria · intriga secundaria · subplot',
      d:'Línea de acción paralela a la principal, con personajes y conflicto propios.',
      u:'La buena subtrama refleja, contrasta o complica la principal, trata el mismo tema desde otro ángulo y se cruza con ella en un momento decisivo. Da respiro y permite cortar con ganchos.',
      c:'Si puede quitarse sin que cambie nada en la trama principal, es otro libro.',
      x:['*Ana Karénina*: Levin y Kitty frente a Ana y Vronski.', '*El rey Lear*: Gloucester y sus hijos reflejan a Lear y sus hijas.', '*Don Quijote*: el gobierno de Sancho en la ínsula Barataria, en paralelo a las burlas de los duques a don Quijote.'],
      t:'Cada subtrama es un Arco narrativo con su franja; las Ramas y las convergencias muestran dónde nace y dónde vuelve a unirse a la principal.',
      s:['Montaje paralelo', 'Entrelazamiento', 'Personaje contraste'] },
    { n:'Prólogo y epílogo', a:'Marco del libro · antes y después',
      d:'Textos separados del cuerpo de la narración: el prólogo la precede (otra época, otro punto de vista, un suceso que la enmarca); el epílogo la sigue, normalmente tras un salto temporal.',
      u:'Un prólogo se justifica si da algo que el primer capítulo no puede dar: una amenaza, un enigma, una voz distinta. Haga que sea breve y que plantee una pregunta. El epílogo muestra el precio y el eco de lo ocurrido.',
      c:'El prólogo enciclopédico (la historia del reino en cinco páginas) es el arranque que más lectores pierde. Si el prólogo es solo el primer capítulo con otro nombre, quítele el nombre.',
      x:['El «Prólogo al lector» del *Quijote*, donde Cervantes juega con la escritura de prólogos.', 'El prólogo de *Romeo y Julieta*, que cuenta el final.', 'El epílogo de *Guerra y paz*.', 'El falso manuscrito encontrado que abre *El nombre de la rosa*.'],
      s:['Gancho', 'Desenlace', 'Exposición dosificada', 'Relato enmarcado'] }
  ]}
]});

/* ============ TÉCNICAS NARRATIVAS ============ */
SUPPORT.push({ key:'tecnicas', name:'Técnicas narrativas', kicker:'Técnica',
  intro:'El oficio de llevar la historia a la página: cómo se construye una escena, cómo se gobierna la velocidad, cómo se ordenan las partes, cómo se entra en la cabeza de los personajes y qué juego se establece con el lector. Si los recursos narrativos son lo que pasa en la historia, las técnicas son la manera de contarlo. Varias llevan también el nombre que les dio Mario Vargas Llosa en *Cartas a un joven novelista* (1997): las cajas chinas, los vasos comunicantes, el dato escondido.',
  groups:[
  { name:'Escena y ritmo', items:[
    { n:'Mostrar, no contar', a:'Show, don’t tell · mostrar, no decir',
      d:'En lugar de afirmar un estado o una cualidad («estaba nerviosa», «era generoso»), presentar las acciones, los gestos, las palabras y los detalles que llevan al lector a deducirlo por sí mismo.',
      u:'Muestre lo que importa (emociones, giros, relaciones) y deje que el lector haga la suma. Buena prueba: ¿podría filmarlo una cámara?',
      c:'No es una ley absoluta: contar es imprescindible para resumir, enlazar escenas y dar contexto. Mostrarlo todo hace el libro interminable.',
      x:['Contar: «Rafael estaba furioso».', 'Mostrar: «Rafael dejó el vaso en la mesa con tanto cuidado que todos se callaron».', 'Contar: «Era una casa pobre». / Mostrar: «El linóleo de la cocina estaba gastado hasta el cemento delante de los fogones».'],
      s:['Escena y sumario', 'Detalle significativo', 'Correlato objetivo', 'Subtexto', 'Caracterización directa e indirecta'] },
    { n:'Escena y sumario', a:'Las velocidades del relato (Genette): escena · sumario · elipsis · pausa',
      d:'Escena: el tiempo del relato se acerca al de la historia; acción y diálogo, momento a momento. Sumario: se resume en pocas líneas lo que duró días o años. Con la elipsis (se salta) y la pausa (la acción se detiene para describir o reflexionar), son las cuatro velocidades de que dispone el narrador.',
      u:'Ponga en escena lo que cambia algo (decisiones, enfrentamientos, revelaciones) y en sumario la rutina, los viajes y las transiciones. Alternar las cuatro es lo que da ritmo a un libro.',
      c:'El error clásico es resumir los momentos decisivos y escenificar los triviales.',
      x:['Sumario: «Durante tres años se escribieron todas las semanas».', 'Escena: la mañana en que la carta deja de llegar, y lo que ella hace ese día.', '*Cien años de soledad* cubre un siglo combinando sumarios vertiginosos con escenas memorables (el hielo, la lluvia de flores amarillas).'],
      t:'Una Escena del tablero debería corresponder a una escena propiamente dicha; lo que es sumario puede ir en el resumen del Capítulo o en una Nota.',
      s:['Elipsis narrativa', 'Pausa descriptiva', 'Ritmo narrativo', 'Mostrar, no contar'] },
    { n:'Escena y secuela', a:'Scene and sequel (Dwight Swain)',
      d:'Una pareja que se repite a lo largo del libro. La escena de acción tiene objetivo, conflicto y desastre (el personaje no consigue lo que quería o lo consigue con un coste). La secuela tiene reacción (emoción), dilema (¿y ahora qué?) y decisión, que da el objetivo de la escena siguiente.',
      u:'Revise cada escena: ¿qué quiere el personaje, quién o qué se lo impide y cómo acaba peor de lo que empezó? Acorte las secuelas para acelerar; alárguelas para ahondar en el personaje.',
      c:'Encadenar escenas sin secuelas da una novela de acción sin emoción; secuelas sin escenas, una novela de rumiaciones.',
      x:['Escena: Ana va a pedir el préstamo (objetivo); el director de la sucursal es su excuñado (conflicto); se lo niega y amenaza con contarlo todo (desastre).', 'Secuela: Ana llora en el coche (reacción); ¿vender la casa o hablar con su hermano? (dilema); llama a su hermano (decisión → nueva escena).'],
      s:['Ciclos de intento y fracaso', 'Ritmo narrativo', 'Obstáculos y complicaciones'] },
    { n:'Ciclos de intento y fracaso', a:'«Sí, pero...» / «No, y además...»',
      d:'Cada intento del personaje por resolver el problema acaba de una de dos maneras: lo consigue, pero surge una nueva complicación; o fracasa, y la situación empeora. El «sí» y el «no» a secas se reservan para el final.',
      u:'Pregunte en cada escena: «¿consigue lo que quiere?», y elija «sí, pero» o «no, y además». Es la manera más sencilla de garantizar la escalada y de impedir que el centro del libro se estanque.',
      c:'Si todos los ciclos son del mismo tipo y tamaño, la escalada se convierte en repetición.',
      x:['«¿Consigue Indiana Jones el arca? Sí, pero los nazis lo encierran en el pozo de las serpientes. ¿Sale de allí? Sí, pero el arca ya va en un camión...»', '«¿Consigue abrir la caja fuerte? No, y además salta la alarma».'],
      s:['Escena y secuela', 'Obstáculos y complicaciones', 'Regla de tres', 'Curva de Fichte'] },
    { n:'Entrar tarde, salir pronto', a:'Late in, early out',
      d:'Empezar cada escena lo más cerca posible del momento que importa y terminarla en cuanto ese momento se cumple, sin llegadas, saludos, despedidas ni conclusiones.',
      u:'Al revisar, pruebe a cortar el primer y el último párrafo de cada escena. Termine en una imagen, una frase de diálogo o una pregunta, y no en una explicación.',
      c:'Llevado al extremo, el lector pierde pie: si nunca sabe dónde está ni quién habla, necesita una frase de orientación.',
      x:['En vez de «Aparcó, subió las escaleras, llamó al timbre. —Hola, Marta...», empiece por: «—¿Desde cuándo lo sabes? —preguntó Marta, sin dejarle entrar».'],
      s:['Elipsis narrativa', 'In medias res', 'Capítulos cortos y ganchos'] },
    { n:'Elipsis narrativa', a:'Salto temporal · el dato escondido (Vargas Llosa)',
      d:'Omisión de un período de la historia: el relato se salta horas, días o años. Puede señalarse («Dos años después») o quedar implícita (una línea en blanco). Vargas Llosa llama «dato escondido» a la omisión significativa: lo que se calla para que pese más.',
      u:'Sáltese todo lo que el lector puede adivinar. La elipsis también esconde: omitir el momento crucial (el crimen, la noche, la conversación) crea un vacío que el lector llena y que puede revelarse más tarde.',
      c:'Una elipsis mal señalada desorienta: el lector tiene que saber pronto cuánto tiempo ha pasado y dónde está.',
      x:['*La educación sentimental* (Flaubert): «Viajó», y pasan años.', 'El hueso que se convierte en nave espacial en *2001: una odisea del espacio*: millones de años en un plano.', '*Los cachorros* (Vargas Llosa): la mutilación de Cuéllar, nunca nombrada del todo, lo explica todo.', '«Colinas como elefantes blancos» (Hemingway): la palabra «aborto» no aparece nunca.'],
      s:['Escena y sumario', "Elipsis (figura)", 'Teoría del iceberg', 'Entrar tarde, salir pronto'] },
    { n:'Pausa descriptiva', a:'Pausa · digresión',
      d:'Suspensión de la acción para describir, comentar o divagar. En la digresión, el narrador se aparta del hilo de la historia para reflexionar, contar otra cosa o hablar con el lector.',
      u:'La pausa frena: úsela después de un pico de tensión, para que el lector respire, o antes, para hacerle esperar. La digresión es un placer cuando la voz del narrador vale por sí misma.',
      c:'Una pausa en el momento equivocado mata el suspense; quien tiene prisa por la trama se la salta.',
      x:['*Tristram Shandy* (Sterne): la digresión como principio de composición.', '*Moby Dick*: los capítulos sobre ballenas y balleneros.', '*Los miserables*: Waterloo, las cloacas de París.', 'El discurso de la Edad de Oro y el de las armas y las letras en el *Quijote*.'],
      s:['Descripción', 'Escena y sumario', 'Ritmo narrativo', 'Narrador intruso'] },
    { n:'Ritmo narrativo', a:'Tempo · pacing',
      d:'La velocidad a la que avanza la historia y a la que el lector la siente pasar. Depende de la proporción entre escena y sumario, de la longitud de capítulos, párrafos y frases, y de la frecuencia de los acontecimientos.',
      u:'Se acelera con escenas cortas, diálogo, frases breves, cortes y elipsis; se frena con descripción, interioridad, frases largas y secuelas. Alterne tensión y descanso: un libro siempre a la carrera cansa tanto como uno siempre parado.',
      c:'El ritmo no es velocidad: un libro lento puede tener un ritmo perfecto. El fallo es la monotonía, no la lentitud.',
      x:['Los thrillers: capítulos de dos páginas, alternancia de hilos, un reloj en marcha.', 'Paradoja útil: en los momentos de máxima tensión, frene; narre el segundo decisivo con todo detalle, a cámara lenta.'],
      t:'En el tablero, la cantidad de Escenas por Capítulo y la alternancia de Arcos narrativos dan una imagen del ritmo del libro.',
      s:['Escena y sumario', 'Ritmo de la frase', 'Capítulos cortos y ganchos', 'Escena y secuela'] },
    { n:'Capítulos cortos y ganchos', a:'Fragmentación del capítulo',
      d:'Dividir la narración en unidades breves, cada una con su pequeño giro, que terminan en suspenso.',
      u:'Cada capítulo debe cambiar algo y dejar una pregunta abierta. Termine en mitad de la acción y retómela más tarde. Los títulos de capítulo también pueden prometer, engañar o ironizar.',
      c:'En exceso, parece mecánico. Un capítulo largo y tranquilo en el sitio justo da peso.',
      x:['*Memorias póstumas de Blas Cubas* (Machado de Assis): capítulos de pocas líneas, alguno solo con puntuación.', '*El código Da Vinci*: más de cien capítulos.', 'La novela por entregas: *Los misterios de París* (Eugène Sue), los folletines de Galdós y Pérez Escrich.', 'Los títulos de capítulo del *Quijote*, que anuncian, resumen y a menudo bromean.'],
      t:'En el tablero, arrastre Escenas entre Capítulos para probar dónde cae el corte.',
      s:['Gancho', 'Montaje paralelo', 'Ritmo narrativo'] }
  ]},
  { name:'Arquitectura del relato', items:[
    { n:'Relato enmarcado', a:'Marco narrativo · historia dentro de la historia · cajas chinas (Vargas Llosa) · muñecas rusas',
      d:'Un relato sirve de marco a otro u otros, contados por personajes del primero. Cada historia contada dentro de otra baja un nivel. Vargas Llosa lo llama «cajas chinas».',
      u:'El marco justifica el acto de contar, crea un oyente y permite comentar y dudar del relato interior. La relación entre los dos niveles (eco, contraste, explicación) es lo que da sentido.',
      c:'Si el marco no tiene tensión propia, es solo un retraso.',
      x:['*El conde Lucanor* (don Juan Manuel, 1335): cada cuento es la respuesta de Patronio a un problema del conde.', '*Las mil y una noches*; el *Decamerón* (Boccaccio); *Los cuentos de Canterbury* (Chaucer).', '*Frankenstein*: las cartas de Walton contienen el relato de Victor, que contiene el de la criatura.', 'La novela de *El curioso impertinente*, leída en la venta en mitad del *Quijote*.'],
      s:['Mise en abyme', 'Autor, narrador y narratario', 'Metalepsis'] },
    { n:'Mise en abyme', a:'Puesta en abismo · construcción en abismo · relato en espejo',
      d:'Una obra que contiene, en pequeño, una imagen de sí misma: una historia, obra de teatro, cuadro o libro, dentro de la historia, que refleja el conjunto.',
      u:'Condensa el tema, anuncia el desenlace o desenmascara a un personaje. Debe percibirse como reflejo sin necesidad de explicarlo.',
      c:'Si el narrador explica el paralelismo, pierde toda su fuerza.',
      x:['La obra dentro de la obra en *Hamlet*, que escenifica el crimen del rey.', 'En la segunda parte del *Quijote*, los personajes ya han leído la primera.', '*Las meninas* (Velázquez), en pintura.', '*Los monederos falsos* (Gide): un novelista escribe una novela llamada *Los monederos falsos*.'],
      s:['Relato enmarcado', 'Metaficción', 'Presagio'] },
    { n:'Montaje paralelo', a:'Alternancia · vasos comunicantes (Vargas Llosa) · cross-cutting',
      d:'Alternar dos o más líneas de acción que transcurren a la vez, en lugares o con personajes distintos. Vargas Llosa habla de «vasos comunicantes» cuando las líneas, al alternarse, se contaminan y se modifican mutuamente.',
      u:'Corte de una línea a otra en un momento de tensión; haga que se hagan eco (el mismo gesto, la misma palabra) y que converjan en el clímax. La alternancia puede acelerarse a medida que se acerca el final.',
      c:'Si una línea es mucho más débil, el lector se la salta; asegúrese de que todas tienen su pregunta y su avance propios.',
      x:['*La casa verde* (Vargas Llosa): cinco historias en tiempos y lugares distintos, alternadas hasta en la misma frase.', '*El señor de los anillos*: Frodo y Sam por un lado, la guerra por el otro.', 'El bautizo de *El padrino*: la ceremonia alternada con las ejecuciones.', '*Patria* (Aramburu): dos familias de un pueblo vasco, capítulo a capítulo.'],
      t:'Es exactamente lo que muestra el tablero: cada Arco narrativo en su franja y el orden narrativo alternando entre ellas.',
      s:['Entrelazamiento', 'Subtrama', 'Gancho', 'Novela coral'] },
    { n:'Entrelazamiento', a:'Relato entrelazado · hilos que divergen y convergen',
      d:'Varias líneas narrativas que avanzan en paralelo, se separan de un tronco común y vuelven a encontrarse. Viene de los libros de caballerías medievales (el *entrelacement* francés).',
      u:'Planifique los puntos de contacto: dónde nace un hilo de otro, dónde se cruzan y qué información pasa en ese cruce. Una convergencia bien preparada es una de las mayores recompensas para el lector.',
      c:'Demasiados hilos sin convergencia a la vista dispersan al lector; cada separación debe prometer un reencuentro.',
      x:['Los relatos artúricos y el *Orlando furioso* (Ariosto); el *Amadís de Gaula*.', '*El señor de los anillos*: la Compañía se separa y se reencuentra.', '«El jardín de senderos que se bifurcan» (Borges): una novela en la que todas las ramas ocurren a la vez.', '*El atlas de las nubes* (David Mitchell): seis historias encajadas y enlazadas.'],
      t:'Las Ramas (un Arco narrativo que diverge de otro) y las convergencias (un Arco narrativo que se une a otro) existen para dibujar esto.',
      s:['Montaje paralelo', 'Subtrama', 'Novela fragmentaria'] },
    { n:'Narración no lineal', a:'Anacronía · cronología fragmentada',
      d:'El orden en que se cuentan los hechos no coincide con el orden en que ocurrieron: hacia atrás, hacia delante, en espiral o en fragmentos barajados.',
      u:'Ordene los episodios según la lógica de la emoción o de la revelación, no del calendario. Dé al lector anclas (fechas, edades, estaciones, un peinado) para orientarse.',
      c:'El desorden tiene que producir una ganancia (suspense, ironía, sentido) que el orden directo no daría.',
      x:['*Pedro Páramo* (Rulfo): fragmentos de vivos y muertos sin orden cronológico.', '*La muerte de Artemio Cruz* (Carlos Fuentes): la agonía del presente intercalada con doce días decisivos de su vida.', '*Matadero cinco* (Vonnegut): Billy Pilgrim «se ha soltado del tiempo».', '*Memento* (Nolan), contada de atrás hacia delante; *Pulp Fiction*.'],
      t:'Compare, en la ficha de cada Arco narrativo, el orden narrativo con el orden cronológico.',
      s:['Analepsis', 'Prolepsis', 'Novela fragmentaria', 'Estructura circular'] },
    { n:'Novela fragmentaria', a:'Narración en mosaico · novela collage',
      d:'El libro se compone de fragmentos, episodios, voces o documentos sueltos que solo en conjunto forman una figura.',
      u:'Cada fragmento debe valer por sí mismo y aportar una pieza. La unidad viene de un lugar, de un suceso o de un tema común.',
      c:'Sin un hilo (aunque sea secreto), el mosaico se queda en cajón de sastre.',
      x:['*Rayuela* (Cortázar): capítulos que pueden leerse en más de un orden, con un «tablero de dirección».', '*La verdad sobre el caso Savolta* (Eduardo Mendoza): recortes de prensa, declaraciones y relato.', '*Las ciudades invisibles* (Calvino).', '*Libro del desasosiego* (Pessoa / Bernardo Soares).'],
      s:['Narración no lineal', "Narración epistolar o documental", 'Novela coral'] },
    { n:'Efecto Rashomon', a:'Versiones contradictorias · perspectivismo',
      d:'El mismo suceso es contado por varios personajes en versiones incompatibles, sin que el texto decida cuál es la verdadera. En la crítica española se habla también de «perspectivismo» (Ortega y Gasset, Pérez de Ayala).',
      u:'Cada versión debe revelar quién la cuenta: sus intereses, su vanidad, su culpa. El lector se convierte en juez.',
      c:'Si las versiones solo difieren en detalles sin consecuencia, el efecto se queda en ejercicio.',
      x:['*Rashomon* (Kurosawa), a partir de relatos de Akutagawa.', '*El ruido y la furia* y *Mientras agonizo* (Faulkner).', '*Belarmino y Apolonio* (Pérez de Ayala, 1921): el mismo asunto visto desde varios ángulos.', '*Los detectives salvajes* (Bolaño): decenas de testigos hablan de dos poetas que apenas aparecen.'],
      s:['Focalización', 'Narrador no fiable', 'Novela coral'] },
    { n:'Novela coral', a:'Protagonista colectivo · novela de personaje múltiple',
      d:'Novela sin un único protagonista: un grupo, un barrio, un pueblo o una ciudad se cuentan a través de muchos personajes que se cruzan, con peso parecido.',
      u:'Dé a cada personaje un deseo propio y un rasgo reconocible (una forma de hablar, una manía) para que el lector no los confunda. Busque un espacio o un tiempo que los reúna (un café, unos días, una catástrofe) y escenas donde se crucen.',
      c:'El mayor riesgo es la dispersión: decenas de personajes que el lector no distingue. Limite los que tienen punto de vista y deje los demás en el fondo.',
      x:['*La colmena* (Cela, 1951): unos trescientos personajes del Madrid de posguerra en unos pocos días.', '*Manhattan Transfer* (Dos Passos).', '*Los recuerdos del porvenir* (Elena Garro): el pueblo de Ixtepec cuenta en primera persona del plural.', '*Patria* (Aramburu).'],
      t:'Un Arco narrativo por personaje o por grupo y las convergencias del tablero permiten ver si algún hilo desaparece durante demasiados Capítulos.',
      s:['Montaje paralelo', 'Entrelazamiento', 'Novela fragmentaria'] }
  ]},
  { name:'Interioridad, personaje y diálogo', items:[
    { n:'Monólogo interior', a:'Monólogo interior directo e indirecto · corriente de conciencia',
      d:'Reproducción del pensamiento de un personaje tal como él lo formula para sí. Puede ser directo (en primera persona, sin mediación del narrador) o indirecto (filtrado por el narrador). Llevado al extremo de la asociación libre, se convierte en flujo de conciencia.',
      u:'Úselo en los momentos de decisión, duda o reacción: las secuelas. El pensamiento debe tener la sintaxis y las obsesiones del personaje, y puede contradecir lo que dice en voz alta.',
      c:'Los personajes que piensan lo obvio o repiten lo que la escena ya ha mostrado frenan el ritmo.',
      x:['El monólogo de Molly Bloom al final de *Ulises* (Joyce).', '*Cinco horas con Mario* (Delibes, 1966): Carmen habla al cadáver de su marido durante toda la novela.', '*Tiempo de silencio* (Martín-Santos): los pensamientos de Pedro, con su jerga científica.', 'Los soliloquios de Segismundo y de Hamlet, el equivalente en el teatro.'],
      s:['Flujo de conciencia', 'Estilo indirecto libre', 'Distancia narrativa', 'Escena y secuela'] },
    { n:'Subtexto', a:'Lo no dicho',
      d:'Lo que los personajes quieren decir, sienten u ocultan debajo de lo que dicen realmente. El diálogo es la superficie; el subtexto, la corriente.',
      u:'Haga que los personajes hablen de otra cosa (el tiempo, la cena, un mueble) mientras discuten lo que no pueden nombrar. Deles objetivos opuestos en la conversación. Los gestos pueden desmentir las palabras.',
      c:'El diálogo «subrayado», en el que cada uno dice exactamente lo que siente, suena falso.',
      x:['«Colinas como elefantes blancos» (Hemingway): una pareja discute un aborto sin decir nunca la palabra.', 'Las obras de Chéjov y de Harold Pinter.', '*El Jarama* (Sánchez Ferlosio): conversaciones banales a la orilla del río, cargadas de lo que nadie dice.', '«—Hace frío. —¿Quieres mi chaqueta? —No. Quiero irme a casa».'],
      s:['Teoría del iceberg', 'Mostrar, no contar', 'Reticencia', 'Eufemismo'] },
    { n:'Teoría del iceberg', a:'Teoría de la omisión (Hemingway)',
      d:'Solo una pequeña parte de la historia aparece en la superficie del texto; el resto (el pasado, los motivos, la emoción) queda sumergido y sostiene lo que se ve. El escritor puede omitir lo que conoce bien: el lector lo sentirá.',
      u:'Sepa mucho más de lo que cuenta. Corte explicaciones, adjetivos de emoción y antecedentes; conserve los hechos, los gestos y las palabras.',
      c:'Solo se puede omitir lo que se sabe: omitir por ignorancia deja agujeros, no profundidad.',
      x:['Hemingway: en «El gran río de los dos corazones», la guerra no se menciona nunca.', 'Los cuentos de Raymond Carver.', '«¡Diles que no me maten!» (Rulfo): un crimen antiguo y toda una vida en unas pocas frases de diálogo.', '*Lo que queda del día* (Ishiguro): el amor que el mayordomo nunca nombra.'],
      s:['Subtexto', "Frase breve", 'Mostrar, no contar', 'Construcción de mundos'] },
    { n:'Caracterización directa e indirecta', a:'Retrato del personaje',
      d:'Directa: el narrador (u otro personaje) dice cómo es el personaje. Indirecta: el personaje se revela por lo que hace, dice, piensa, viste y posee, por el medio en que vive y por el efecto que causa en los demás.',
      u:'Preséntelo con un rasgo directo, si quiere, y confírmelo (o desmiéntalo) con acciones. Lo que el personaje hace bajo presión vale más que todo lo que se diga de él. Un nombre, una casa y un objeto también caracterizan.',
      c:'El retrato completo de presentación (pelo, ojos, estatura, virtudes) frena la acción y se olvida; reparta los rasgos y elija los que cuentan algo.',
      x:['Directa: «Era un hombre avaro».', 'Indirecta: «Contó las monedas dos veces antes de entregarlas y se quedó mirándolas en la mano del otro».', 'El clérigo de Maqueda en el *Lazarillo*: la llave del arca colgada del sayo dice más que cualquier adjetivo.'],
      t:'La ficha del Personaje guarda la descripción; las Escenas en las que aparece muestran dónde se pone a prueba.',
      s:['Mostrar, no contar', 'Detalle significativo', "Idiolecto y marcas de oralidad", 'Personaje tipo'] },
    { n:'Exposición dosificada', a:'Información en gotas · exposición integrada · incluing',
      d:'Dar al lector la información que necesita (pasado, reglas del mundo, relaciones) poco a poco, dentro de la acción y del diálogo, en vez de volcarla en bloque.',
      u:'Dé cada dato en el momento en que hace falta, y a ser posible como arma de conflicto (en una discusión, en una mentira). Un recién llegado que no conoce el ambiente justifica las explicaciones. Cree primero la curiosidad y después responda.',
      c:'A evitar: el prólogo enciclopedia y el diálogo de «como ya sabes», en el que dos personajes se dicen lo que ambos saben.',
      x:['Mal: «—Como sabes, hermano, nuestro padre, el rey, murió hace diez años en la batalla del Vado».', 'Mejor: «—No me hables del Vado. Tú ni siquiera estabas allí».', 'Watson, Bilbo, Harry Potter: el recién llegado al que hay que explicárselo todo.'],
      s:['Construcción de mundos', 'In medias res', 'Estilo directo', 'Confidente'] },
    { n:'Construcción de mundos', a:'Worldbuilding · creación de mundos',
      d:'La invención coherente del universo de la historia: geografía, historia, política, economía, creencias, tecnología o magia y sus reglas. Sirve para la fantasía y la ciencia ficción, pero también para una novela histórica o un pueblo inventado.',
      u:'Establezca reglas y límites y respételos: un sistema de magia vale por lo que no puede hacer y por lo que cuesta. Muestre el mundo a través de la vida diaria de los personajes (qué comen, qué temen, cómo maldicen).',
      c:'El mundo es un iceberg: nueve décimas partes se quedan en las notas del autor.',
      x:['La Tierra Media (Tolkien), con lenguas y mitología propias.', 'Macondo (García Márquez); Santa María (Onetti); Región (Juan Benet); el condado de Yoknapatawpha (Faulkner).', '«Tlön, Uqbar, Orbis Tertius» (Borges): un mundo inventado que acaba invadiendo el real.', '*Dune* (Frank Herbert): ecología, religión y política de un planeta.'],
      t:'Las Referencias y las Notas son el lugar para la «biblia» del mundo: mapas, cronologías, reglas, imágenes, asociadas a los Tomos, Arcos narrativos y Escenarios a los que se refieren.',
      s:['Exposición dosificada', 'Teoría del iceberg', 'Verosimilitud', 'Biblia de la serie', 'Neologismo'] }
  ]},
  { name:'Juego con el lector', items:[
    { n:'Verosimilitud', a:'Suspensión de la incredulidad (Coleridge) · pacto ficcional',
      d:'La cualidad de parecer verdadero dentro de las reglas de la propia historia. No es realismo: un dragón puede ser verosímil y una coincidencia real puede no serlo. El lector acepta suspender la incredulidad mientras el texto cumpla las reglas que ha establecido.',
      u:'Establezca pronto el pacto (género, tono, reglas) y sea coherente. Lo imposible se acepta mejor que lo improbable; los detalles concretos compran la confianza del lector.',
      c:'«¡Pero si pasó de verdad!» nunca es un argumento: la ficción tiene que ser más plausible que la vida.',
      x:['Aristóteles: es preferible lo imposible verosímil a lo posible increíble.', '*La metamorfosis*: aceptada la premisa, todo lo demás es rigurosamente lógico.', 'Cervantes, en el *Quijote*, sobre los libros de caballerías: las fábulas deben «casarse» con el entendimiento de quien las lee.'],
      s:['Deus ex machina', 'Construcción de mundos', 'Realismo mágico', 'Detalle significativo'] },
    { n:'Metaficción', a:'Ruptura de la cuarta pared · autorreferencia',
      d:'Ficción que llama la atención sobre el hecho de ser ficción: el narrador comenta la escritura, habla con el lector, discute los personajes como invenciones, o el libro se toma a sí mismo como tema.',
      u:'Crea complicidad, humor y reflexión sobre el propio acto de contar. Puede ser un guiño ocasional o la arquitectura entera del libro.',
      c:'Recuerda al lector que nada de aquello es real, lo que puede romper la emoción.',
      x:['El *Quijote*: Cide Hamete Benengeli, el manuscrito encontrado en Toledo, el *Quijote* apócrifo de Avellaneda discutido por los personajes.', '*Niebla* (Unamuno), que su autor llamó «nivola».', '*Si una noche de invierno un viajero* (Calvino).', '*El cuarto de atrás* (Carmen Martín Gaite); *La mujer del teniente francés* (John Fowles), con dos finales.'],
      s:['Metalepsis', 'Narrador intruso', 'Mise en abyme', 'Intertextualidad', 'Nivola'] },
    { n:'Metalepsis', a:'Transgresión de niveles narrativos',
      d:'Transgresión de las fronteras entre niveles narrativos: el autor entra en la historia, un personaje sale del libro, el narrador interviene en lo que cuenta, el lector es arrastrado dentro.',
      u:'Produce vértigo, humor o inquietud. Funciona mejor cuando el texto ha establecido primero fronteras nítidas.',
      c:'Si se repite, pierde el efecto de vértigo y se vuelve un tic.',
      x:['«Continuidad de los parques» (Cortázar): el lector de una novela es la víctima del crimen que está leyendo.', '*Niebla* (Unamuno): Augusto Pérez va a Salamanca a discutir su destino con el autor.', '*La rosa púrpura de El Cairo* (Woody Allen): el personaje sale de la pantalla.', '*La historia interminable* (Michael Ende).'],
      s:['Metaficción', 'Relato enmarcado', 'Mise en abyme'] },
    { n:'Extrañamiento', a:'Desautomatización · desfamiliarización · ostranenie (Shklovski)',
      d:'Presentar lo conocido como si se viera por primera vez, para que el lector lo vea de verdad en lugar de limitarse a reconocerlo.',
      u:'Describa sin usar el nombre habitual de la cosa; adopte el punto de vista de un niño, un extranjero, un animal o un extraterrestre; cambie la escala. Es la cura contra el lugar común.',
      c:'El efecto se agota si todo el libro lo usa sin variación: la mirada extrañada necesita algo que descubrir.',
      x:['«Jolstomer» (Tolstói): la propiedad privada explicada por un caballo.', '*Cartas persas* (Montesquieu); *Cartas marruecas* (Cadalso, 1789): España vista por un viajero marroquí.', '*Los viajes de Gulliver* (Swift).', '«Instrucciones para subir una escalera» (Cortázar, *Historias de cronopios y de famas*).'],
      s:['Lugar común', 'Focalización', 'Imágenes sensoriales'] },
    { n:'Realismo mágico', a:'Lo real maravilloso (Carpentier)',
      d:'Lo sobrenatural irrumpe en un mundo realista y se narra con toda naturalidad, sin asombro del narrador ni de los personajes. Alejo Carpentier propuso, en el prólogo de *El reino de este mundo* (1949), lo «real maravilloso» americano: lo prodigioso que ya está en la historia y la naturaleza de América.',
      u:'El tono es la clave: cuente el prodigio en el mismo registro con que se cuenta el precio del pan, y con detalles exactos. Lo mágico suele ser la cara visible de una verdad histórica, social o emocional.',
      c:'No es fantasía con reglas explicadas: lo mágico no se justifica. Imitarlo con mariposas amarillas y abuelas que levitan, sin la verdad que hay detrás, da un pastiche.',
      x:['*Cien años de soledad*: Remedios la Bella sube al cielo mientras tiende sábanas.', '*Pedro Páramo* (Rulfo): un pueblo de muertos que siguen hablando.', '*La casa de los espíritus* (Isabel Allende); *Como agua para chocolate* (Laura Esquivel).', '*Memorial del convento* (Saramago): Blimunda ve el interior de las personas.'],
      s:['Verosimilitud', 'Tono', 'Alegoría', 'Boom latinoamericano'] },
    { n:'Escritura con restricciones', a:'Constricción · Oulipo · lipograma',
      d:'Imponer al texto una regla formal arbitraria: no usar una letra, seguir un esquema matemático, contar la misma historia de noventa y nueve maneras.',
      u:'La restricción obliga a encontrar soluciones que nunca se le ocurrirían a uno en libertad. Es un ejercicio excelente: reescribir una escena sin adjetivos, solo en diálogo, en una sola frase, en exactamente cien palabras.',
      c:'Si el lector solo ve la proeza y no la historia, la restricción se ha comido el texto.',
      x:['*Ejercicios de estilo* (Raymond Queneau): el mismo episodio banal contado de 99 maneras.', '*La disparition* (Georges Perec): una novela entera sin la letra «e»; la traducción española, *El secuestro*, prescinde de la «a».', '*La vida instrucciones de uso* (Perec): un edificio recorrido como un tablero de ajedrez.', 'El microrrelato y el haiku.'],
      s:['Pastiche y parodia', 'Novela fragmentaria', 'Microrrelato'] }
  ]}
]});

/* ============ MÉTODOS NARRATIVOS ============ */
SUPPORT.push({ key:'metodos', name:'Métodos narrativos', kicker:'Método',
  intro:'Modelos y procesos para planificar, estructurar y revisar una narración larga. Las estructuras describen la forma que suelen tener las historias; los métodos de trabajo dicen cómo llegar a ella. Ninguno es una receta: son mapas para cuando uno se pierde y listas de comprobación para cuando algo no funciona. Varios describen la misma curva con nombres distintos; elija el que mejor le hable, o combínelos. Incluimos también la tradición escolar hispánica (planteamiento, nudo y desenlace) y lo que pensaron sobre el oficio Quiroga y Piglia.',
  groups:[
  { name:'Estructuras de la trama', items:[
    { n:'Planteamiento, nudo y desenlace', a:'Introducción, desarrollo y desenlace · la estructura escolar clásica',
      d:'La división tradicional que se enseña en la escuela hispánica, heredera del principio, medio y fin de Aristóteles: el planteamiento presenta personajes, lugar y conflicto; el nudo complica la situación hasta el punto de máxima tensión; el desenlace la resuelve.',
      u:'Sirve como primera comprobación de cualquier relato, sobre todo del cuento: ¿hay un conflicto claro en el planteamiento?, ¿se complica en el nudo?, ¿se resuelve (o se cierra con intención) en el desenlace? Para una novela, desarróllela con la estructura en tres actos o con la de siete puntos.',
      c:'Es demasiado general para planificar una novela: no dice nada del enorme nudo central. Y no obliga a contar en ese orden; un relato puede empezar por el desenlace.',
      x:['«El almohadón de plumas» (Quiroga): planteamiento, el matrimonio frío y la casa hostil; nudo, la enfermedad inexplicable de Alicia; desenlace, el parásito en el almohadón.', '*Lazarillo de Tormes*: el niño sale de casa (planteamiento); los amos (nudo); el «buen puerto» de Lázaro, casado con la criada del arcipreste (desenlace irónico).'],
      t:'Puede marcar las tres partes en los nombres de los Capítulos o usar tres Tomos para una obra larga.',
      s:['Estructura en tres actos', 'Pirámide de Freytag', 'Clímax', 'Desenlace'] },
    { n:'Estructura en tres actos', a:'Planteamiento · confrontación · resolución (Syd Field)',
      d:'El modelo más difundido, con raíces en Aristóteles y fijado para el cine por Syd Field. Acto I (en torno al 25 %): el mundo, el protagonista, el incidente incitador y la decisión que lo lanza a la aventura. Acto II (50 %): obstáculos crecientes, punto medio, crisis. Acto III (25 %): clímax y desenlace.',
      u:'Buen primer mapa para cualquier historia. Marque cinco momentos (incidente incitador, primer punto de giro, punto medio, segundo punto de giro o «todo está perdido», clímax) y compruebe si están más o menos en su sitio.',
      c:'Los porcentajes son medias, no leyes. El segundo acto es largo: divídalo en dos por el punto medio.',
      x:['*Orgullo y prejuicio*: I, llegada de Bingley y Darcy; II, rechazo, carta, Pemberley, fuga de Lydia; III, segunda declaración.', '*La guerra de las galaxias*: I, Tatooine; II, la Estrella de la Muerte; III, la batalla final.'],
      t:'Puede usar los Tomos como actos de una historia, o marcar los actos en los nombres de los Capítulos.',
      s:['Incidente incitador', 'Punto de no retorno', 'Punto medio', 'Todo está perdido', 'Clímax', 'Pirámide de Freytag'] },
    { n:'Pirámide de Freytag', a:'Estructura en cinco actos',
      d:'Modelo propuesto por Gustav Freytag en 1863 a partir de la tragedia clásica y de Shakespeare: exposición, acción ascendente, clímax (aquí en el centro: el punto de giro del destino del héroe), acción descendente y catástrofe o desenlace.',
      u:'Útil para tragedias e historias de caída, en las que el héroe alcanza la cima en el centro y la segunda mitad es la consecuencia. En las historias modernas el clímax suele estar mucho más cerca del final.',
      c:'Aplicada a una novela de suspense, la pirámide deja una segunda mitad sin tensión ascendente.',
      x:['*Macbeth*: sube hasta el asesinato de Banquo y el banquete (acto III); a partir de ahí, cae.', '*Romeo y Julieta*: la muerte de Teobaldo, en el centro, lo cambia todo.', '*El caballero de Olmedo* (Lope de Vega): la dicha de los amantes culmina en la fiesta y desde ahí todo conduce a la muerte anunciada por la copla.'],
      s:['Estructura en tres actos', 'Clímax', 'Desenlace', 'Anagnórisis y peripecia'] },
    { n:'El viaje del héroe', a:'Monomito (Joseph Campbell) · doce etapas (Christopher Vogler)',
      d:'Patrón común a mitos de todo el mundo, descrito por Campbell en *El héroe de las mil caras* (1949) y adaptado a la escritura por Vogler en *El viaje del escritor*. Las doce etapas: mundo ordinario; llamada a la aventura; rechazo de la llamada; encuentro con el mentor; travesía del primer umbral; pruebas, aliados y enemigos; acercamiento a la caverna más profunda; odisea (la prueba suprema); recompensa; camino de regreso; resurrección; regreso con el elixir.',
      u:'Excelente para aventura, fantasía e historias de crecimiento. Lea las etapas como funciones, no como escenas obligatorias: pueden cambiar de orden, fundirse o faltar.',
      c:'Seguido al pie de la letra, produce historias previsibles.',
      x:['La *Odisea*; *El hobbit*; *La guerra de las galaxias* (George Lucas se inspiró directamente en Campbell).', '*Harry Potter y la piedra filosofal*; *El rey león*; *Matrix*.'],
      s:['Mentor', 'Punto de no retorno', 'Arco de personaje', 'Story Circle', 'El viaje de la heroína'] },
    { n:'El viaje de la heroína', a:'Maureen Murdock (1990)',
      d:'Respuesta al viaje del héroe, centrada en una búsqueda interior. A grandes rasgos: separación de lo femenino; identificación con lo masculino y conquista del éxito según esas reglas; sensación de vacío y aridez; descenso; reencuentro con lo femenino; curación de la herida; integración de las dos partes.',
      u:'Buen modelo para historias en las que el triunfo exterior llega pronto y resulta hueco, y el verdadero recorrido es de reconciliación e identidad, sea cual sea el sexo del personaje.',
      c:'Como todo modelo, no es una plantilla: tomado como molde produce personajes de manual.',
      x:['Aplicaciones frecuentes: *Jane Eyre*; Elsa en *Frozen*; *Brave*; el recorrido de Katniss a lo largo de la trilogía.', '*Nada* (Laforet) puede leerse en esta clave: la búsqueda de un lugar propio fuera de la casa de la calle de Aribau.'],
      s:['El viaje del héroe', 'Arco de personaje', 'Deseo y necesidad'] },
    { n:'Save the Cat', a:'«¡Salva al gato!»: los quince beats de Blake Snyder (2005)',
      d:'Hoja de beats (momentos clave) creada para guiones y adaptada a la novela por Jessica Brody: 1) imagen de apertura; 2) enunciado del tema; 3) planteamiento; 4) catalizador; 5) debate; 6) paso al segundo acto; 7) trama B; 8) diversión y juegos (la promesa de la premisa); 9) punto medio; 10) los malos estrechan el cerco; 11) todo está perdido; 12) noche oscura del alma; 13) paso al tercer acto; 14) final; 15) imagen final. El título viene del consejo de mostrar pronto al héroe haciendo algo que lo vuelva simpático: salvar a un gato.',
      u:'El más detallado de los modelos corrientes: dice qué debe pasar y más o menos cuándo. Excelente para diagnosticar un centro de libro que no avanza. La «trama B» (por lo general, una relación) lleva el tema.',
      c:'Se le acusa de haber uniformado el cine comercial: úselo como diagnóstico, no como molde.',
      x:['La imagen de apertura y la final deben ser el «antes» y el «después» del personaje.', '«Diversión y juegos»: las clases y el quidditch en Hogwarts; el entrenamiento y el comienzo de los Juegos en *Los juegos del hambre*.'],
      s:['Estructura en tres actos', 'Punto medio', 'Todo está perdido', 'Estructura circular', 'Estructura de siete puntos'] },
    { n:'Story Circle', a:'El círculo de Dan Harmon',
      d:'Versión condensada del viaje del héroe en ocho pasos dispuestos en un círculo: 1) un personaje está en su zona de confort; 2) pero quiere algo; 3) entra en una situación desconocida; 4) se adapta; 5) consigue lo que quería; 6) pero paga un precio alto; 7) vuelve a la situación conocida; 8) habiendo cambiado. La mitad superior del círculo es el orden; la inferior, el caos.',
      u:'Sencillo y rápido: sirve para una novela, un capítulo, un episodio o el arco de un personaje secundario. Útil para comprobar si de verdad hay cambio.',
      c:'Su sencillez es también su límite: no dice nada del ritmo ni de cómo repartir los ocho pasos en trescientas páginas.',
      x:['Harmon lo usa en *Community* y *Rick y Morty*, episodio a episodio.', '*El hobbit*: la madriguera (confort) → la aventura (o el empujón) → el mundo exterior → pruebas → el tesoro → la batalla → casa → ya no es el mismo.'],
      s:['El viaje del héroe', 'Estructura circular', 'Arco de personaje'] },
    { n:'Estructura de siete puntos', a:'Seven-point story structure (Dan Wells)',
      d:'Siete hitos: gancho (el estado inicial, opuesto al final); primer giro (entra el conflicto); primer pinzamiento (presión que obliga a actuar); punto medio (de la reacción a la acción); segundo pinzamiento (el peor momento); segundo giro (la última pieza necesaria); resolución.',
      u:'Se planifica de atrás hacia delante: empiece por la resolución, defina el gancho como su contrario, después el punto medio, los dos giros y, por último, los pinzamientos. Puede aplicarse a cada hilo (trama principal, historia de amor, arco interior) y luego entrelazarlos.',
      c:'Si cada hilo tiene sus siete puntos pero nunca coinciden en las mismas escenas, el libro se fragmenta.',
      x:['*Harry Potter y la piedra filosofal*: gancho, el huérfano en la alacena bajo la escalera; resolución, vence a Voldemort y encuentra un hogar.'],
      t:'Un Arco narrativo por hilo, cada uno con sus siete puntos, permite ver si los hitos de hilos distintos caen en las mismas Escenas.',
      s:['Estructura en tres actos', 'Planificar desde el final', 'Punto medio', 'Entrelazamiento'] },
    { n:'Curva de Fichte', a:'Fichtean curve (John Gardner)',
      d:'La historia arranca directamente en la acción ascendente, sin exposición previa, y avanza por una serie de crisis cada vez más graves hasta el clímax, hacia los dos tercios o tres cuartos; sigue una acción descendente breve. El contexto se da por el camino.',
      u:'Buena para thrillers, novelas policiacas, cuentos y cualquier historia que deba atrapar desde la primera página. Cada crisis es un miniclímax con su giro.',
      c:'Crisis tras crisis sin respiro agotan; deje pequeñas pausas para que el lector asimile lo ocurrido.',
      x:['La mayoría de los thrillers y de las novelas de aventuras.', '*El mago de Oz*: tornado, bruja, bosque, monos alados; crisis tras crisis.'],
      s:['In medias res', 'Ciclos de intento y fracaso', 'Obstáculos y complicaciones', 'Exposición dosificada'] },
    { n:'Kishōtenketsu', a:'Estructura en cuatro tiempos de Asia oriental',
      d:'Estructura clásica china, coreana y japonesa: *ki* (introducción), *shō* (desarrollo), *ten* (giro: un elemento nuevo e inesperado, en apariencia sin relación) y *ketsu* (conclusión, que reconcilia el giro con lo anterior). No se basa en un conflicto central: el interés nace del contraste y del cambio de perspectiva.',
      u:'Alternativa para historias contemplativas, de vida cotidiana, de misterio suave, o para capítulos y cuentos. La fuerza está en el giro y en cómo obliga a releer el principio.',
      c:'Sin conflicto, el giro tiene que ser realmente revelador; si no, el relato parece no haber empezado nunca.',
      x:['Las tiras de cuatro viñetas (*yonkoma*) del manga.', 'Películas del estudio Ghibli como *Mi vecino Totoro*.', 'El diseño de niveles de los juegos de Nintendo: presentar una idea, desarrollarla, darle la vuelta, concluir.'],
      s:['Estructura en tres actos', 'Giro argumental', 'Tono'] },
    { n:'Las siete tramas básicas', a:'Christopher Booker (2004)',
      d:'Tesis según la cual casi todas las historias siguen uno de siete patrones: vencer al monstruo; de la pobreza a la riqueza; la búsqueda; viaje y regreso; comedia; tragedia; renacimiento.',
      u:'No es un método de planificación, pero ayuda a entender qué tipo de historia se está contando y qué expectativas trae el lector. Muchos libros combinan dos o tres.',
      c:'Cualquier historia puede encajarse a la fuerza en una de las siete; la clasificación sirve para pensar, no para escribir.',
      x:['Vencer al monstruo: *Beowulf*, *Drácula*, *Tiburón*.', 'De la pobreza a la riqueza: *Cenicienta*, *Grandes esperanzas*.', 'La búsqueda: *El señor de los anillos*. Viaje y regreso: *Alicia en el país de las maravillas*.', 'Tragedia: *Macbeth*, *Bodas de sangre*. Renacimiento: *Cuento de Navidad*.'],
      s:['Premisa y logline', 'El viaje del héroe'] },
    { n:'Cociente MICE', a:'Medio · Idea · Personaje · Evento (Orson Scott Card)',
      d:'Cuatro tipos de hilo narrativo, cada uno con su principio y su final. Medio (*Milieu*): empieza cuando el personaje entra en un lugar y termina cuando sale. Idea (o Indagación): empieza con una pregunta y termina con la respuesta. Personaje: empieza con una insatisfacción consigo mismo y termina con un cambio (o con la aceptación). Evento: empieza con una ruptura del orden y termina con un orden nuevo.',
      u:'Identifique qué hilos abre y ciérrelos en orden inverso, como paréntesis anidados: el primero en abrirse es el último en cerrarse. Explica muchos finales insatisfactorios: el libro respondió a una pregunta que no era la que había planteado.',
      c:'Abrir un hilo de un tipo y cerrarlo como si fuera de otro (plantear un misterio y terminar con un cambio interior sin resolverlo) decepciona.',
      x:['Medio: *Los viajes de Gulliver*. Idea: cualquier novela policiaca. Personaje: *Emma*. Evento: *El señor de los anillos*.', 'Anidamiento: se abre un crimen (Idea), luego la crisis del detective (Personaje); se resuelve primero la crisis y, al final, el crimen.'],
      s:['Pregunta dramática', 'Entrelazamiento', 'Subtrama'] },
    { n:'Morfología del cuento', a:'Las 31 funciones de Vladímir Propp (1928)',
      d:'Análisis de los cuentos maravillosos rusos que identificó 31 funciones (acciones que siempre aparecen en el mismo orden, aunque no todas en cada cuento: alejamiento, prohibición, transgresión, daño, partida del héroe, prueba, objeto mágico, combate, regreso, reconocimiento, boda...) y siete esferas de acción o papeles: agresor, donante, auxiliar, princesa (y su padre), mandatario, héroe y falso héroe.',
      u:'Útil para escribir o reescribir cuentos de hadas y fantasía, y para pensar los personajes por su función en la trama: ¿quién es el donante?, ¿quién el falso héroe? Un mismo personaje puede ocupar varios papeles.',
      c:'Describe un corpus concreto (el cuento maravilloso ruso); aplicado a una novela realista, solo da metáforas.',
      x:['La prohibición y su transgresión: «No abras esa puerta» en *Barba Azul*.', 'El donante: la anciana que da al héroe el objeto mágico a cambio de un favor.', 'El falso héroe: las hermanastras de Cenicienta que intentan calzarse el zapato.'],
      s:['Cuento tradicional y fábula', 'Personaje tipo', 'El viaje del héroe', 'Mentor'] },
    { n:'Decálogo del perfecto cuentista', a:'Horacio Quiroga (1927)',
      d:'Los diez mandamientos que el uruguayo Horacio Quiroga publicó para los escritores de cuentos. Entre ellos: tener fe ciega en un maestro (Poe, Maupassant, Kipling, Chéjov); no empezar a escribir sin saber adónde se va, porque en un cuento logrado las tres primeras líneas tienen casi la importancia de las tres últimas; no adjetivar sin necesidad; contar como si la historia solo interesara al pequeño mundo de los personajes.',
      u:'Léalo como una poética de la economía: saber el final antes de empezar, cuidar el arranque, no sobrecargar de adjetivos, no escribir bajo el imperio de la emoción. Combínelo con la tesis de Piglia y con la teoría del iceberg.',
      c:'Es un texto de su época y con humor: tomarlo como dogma (la «fe ciega» en un maestro) va contra su espíritu.',
      x:['Quiroga: «El almohadón de plumas», «La gallina degollada», «A la deriva».', 'Cortázar retomó la tradición en «Algunos aspectos del cuento» (1962-1963): la novela gana por puntos, el cuento por *knock-out*.'],
      s:['Cuento', 'Planificar desde el final', 'Teoría del iceberg', 'Las dos historias del cuento'] },
    { n:'Las dos historias del cuento', a:'«Tesis sobre el cuento» (Ricardo Piglia, recogida en *Formas breves*)',
      d:'Según Piglia, un cuento siempre cuenta dos historias: una visible, en primer plano, y otra secreta, cifrada en los intersticios de la primera. El efecto final se produce cuando la historia secreta sale a la superficie.',
      u:'Antes de escribir, defina las dos: lo que se cuenta y lo que de verdad está pasando. Use cada detalle de la historia visible para cifrar la secreta. En el cuento clásico (Poe, Quiroga) la secreta se revela al final; en el moderno (Chéjov, Hemingway) se deja sin contar.',
      c:'Si la historia secreta no está bien construida, el final parece una sorpresa gratuita; si está demasiado a la vista, no hay efecto.',
      x:['Piglia pone como ejemplo una nota de Chéjov: un hombre gana una fortuna en el juego, vuelve a casa y se suicida.', '«Emma Zunz» (Borges): una historia de violación y venganza esconde otra de justicia por el padre.', '«La noche boca arriba» (Cortázar).'],
      s:['Cuento', 'Subtexto', 'Teoría del iceberg', 'Decálogo del perfecto cuentista'] }
  ]},
  { name:'Métodos de trabajo', items:[
    { n:'Planificar o descubrir', a:'Arquitectos y jardineros · escritores de mapa y de brújula · plotters y pantsers',
      d:'Los dos polos del proceso de escritura. El arquitecto lo planifica todo antes de escribir; el jardinero planta una semilla y descubre la historia a medida que escribe (la imagen es de George R. R. Martin). En el ámbito hispánico se habla también de escritores «de mapa» y «de brújula». La mayoría se sitúa en algún punto intermedio.',
      u:'Planificar ahorra reescritura y evita callejones sin salida; descubrir da frescura y sorpresa, pero se paga en la revisión. Un compromiso habitual: conocer el final y dos o tres hitos, y descubrir el camino. E. L. Doctorow lo comparaba con conducir de noche: solo se ve hasta donde llegan los faros, pero así se hace el viaje entero.',
      c:'Ningún polo es mejor. El error es usar el método que no le corresponde a uno: el jardinero obligado a hacer escaletas se bloquea; el arquitecto sin plan se pierde.',
      x:['Arquitectos: J. K. Rowling, con tablas de capítulos y de hilos; John Irving, que escribe primero la última frase.', 'Jardineros: Stephen King, que parte de una situación y la sigue.', 'Mario Vargas Llosa describía su primera versión como un «magma» desordenado que después ordena reescribiendo: descubre primero y planifica después.'],
      s:['Método del copo de nieve', 'Borrador cero', 'Planificar desde el final', 'Escaleta'] },
    { n:'Premisa y logline', a:'Frase resumen · «¿Y si...?»',
      d:'La historia resumida en una o dos frases: quién (protagonista), qué quiere (objetivo), contra quién o qué (obstáculo) y qué está en juego. Muchas nacen de una pregunta: «¿Y si...?».',
      u:'Escríbala antes de empezar y vuelva a ella cuando se pierda. Si no cabe en dos frases, quizá la historia todavía no está clara. Una buena premisa contiene una ironía o una tensión interna.',
      c:'Una premisa no es un tema («una novela sobre la soledad») ni una sinopsis de diez líneas: tiene que tener un protagonista y un conflicto.',
      x:['«¿Y si un hidalgo leyera tantos libros de caballerías que saliera a los caminos a imitarlos?» (*Don Quijote*).', '«¿Y si la muerte dejara de matar?» (*Las intermitencias de la muerte*, Saramago).', '«Un científico da vida a una criatura y la abandona; ella le pide cuentas» (*Frankenstein*).', '«Una chica se ofrece a morir en lugar de su hermana en un concurso televisado en el que solo uno sobrevive».'],
      s:['Pregunta dramática', 'Método del copo de nieve', 'Lo que está en juego'] },
    { n:'Método del copo de nieve', a:'Snowflake Method (Randy Ingermanson)',
      d:'Planificación por expansión sucesiva, como un fractal, en diez pasos: 1) una frase que resume la novela; 2) un párrafo (planteamiento, tres desastres, final); 3) una ficha resumen por personaje (objetivo, motivación, conflicto, epifanía); 4) cada frase del párrafo se convierte en un párrafo: sinopsis de una página; 5) una página por personaje principal, desde su punto de vista; 6) sinopsis de cuatro páginas; 7) fichas completas de los personajes; 8) lista de escenas, en una tabla; 9) (opcional) descripción de cada escena; 10) primer borrador.',
      u:'Ideal para quien disfruta planificando pero quiere margen para ajustar: en cada paso se corrigen los anteriores, y los problemas de estructura aparecen antes de haber escrito trescientas páginas.',
      c:'Puede convertirse en una forma elegante de no empezar a escribir nunca. Ponga fecha al paso 10.',
      x:['Paso 1, para *Orgullo y prejuicio*: «Una joven sin fortuna y de lengua afilada rechaza al hombre más rico que conoce y descubre que se equivocó sobre él y sobre sí misma».', 'Paso 2: una frase para el planteamiento, una para cada uno de los tres desastres y una para el final.'],
      t:'El paso 8, la lista de escenas, es el tablero: una Escena por fila, con su Personaje POV y su resumen.',
      s:['Premisa y logline', 'Escaleta', 'Deseo y necesidad', 'Planificar o descubrir'] },
    { n:'Escaleta', a:'Esquema escena a escena · step outline · fichas',
      d:'Lista ordenada de todas las escenas, cada una resumida en una o dos líneas: quién, dónde, qué cambia. Es la técnica de las tarjetas clavadas en la pared que usan los guionistas, y la de Nabokov, que escribía sus novelas en fichas.',
      u:'Escriba una ficha por escena y barájelas hasta que el orden funcione. En cada escena anote el POV, el objetivo, el conflicto y lo que cambia entre la entrada y la salida. Una escena en la que no cambia nada es candidata a desaparecer.',
      c:'La escaleta no es la novela: no se encariñe con ella hasta el punto de no dejar que la escritura la corrija.',
      x:['Ficha: «12. Cocina, noche. POV Ana. Quiere que su hermano firme la venta de la casa; él se niega y le revela que su madre le dejó una carta. Cambia: Ana ya no confía en su madre».', 'Vladimir Nabokov escribió *Lolita* en fichas que iba reordenando.'],
      t:'Para esto sirve la herramienta: cada Escena es una ficha, se arrastra con una pulsación larga, y las franjas muestran a qué Arco narrativo pertenece.',
      s:['Método del copo de nieve', 'Escena y secuela', 'Revisión por capas', 'Escena y sumario'] },
    { n:'Planificar desde el final', a:'Planificación inversa',
      d:'Empezar por el desenlace (el clímax, la revelación, la imagen final) y construir hacia atrás todo lo que hace falta para llegar a él.',
      u:'Imprescindible en novela policiaca y en historias con giro: primero se decide la verdad y después la manera de esconderla. Pregúntese en cada paso: «para que esto ocurra, ¿qué tuvo que pasar antes?».',
      c:'Si todo está al servicio del final, los personajes pueden volverse piezas; deje que tengan deseos propios en el camino.',
      x:['Agatha Christie empezaba por el crimen y el culpable.', 'Edgar Allan Poe, en «Filosofía de la composición», defiende que toda trama debe elaborarse a partir del desenlace.', 'Quiroga, en su decálogo: no se empieza a escribir sin saber adónde se va.'],
      s:['Estructura de siete puntos', 'Giro argumental', 'Siembra y cosecha', 'Presagio'] },
    { n:'Deseo y necesidad', a:'Querer y necesitar · objetivo, motivación y conflicto (GMC, Debra Dixon)',
      d:'La base de cualquier personaje activo. Deseo: el objetivo exterior, concreto y consciente. Necesidad: la carencia interior, a menudo ignorada por el propio personaje. Entre los dos, una mentira en la que el personaje cree. La fórmula GMC lo resume en una frase: «El personaje quiere [objetivo] porque [motivación], pero [conflicto]».',
      u:'Rellene la frase para cada personaje importante (antagonista incluido), tanto en el plano exterior como en el interior. Kurt Vonnegut aconsejaba que todo personaje quisiera algo, aunque fuera un vaso de agua.',
      c:'Un personaje que no quiere nada concreto no genera escenas; uno cuyo deseo y necesidad coinciden no tiene arco.',
      x:['Elizabeth Bennet quiere casarse por amor y necesita reconocer sus propios prejuicios.', 'Gatsby quiere a Daisy; necesitaba soltar el pasado.', 'Ana Ozores quiere una vida plena y apasionada; necesitaría escapar de Vetusta, y no puede.'],
      t:'La descripción de la ficha del Personaje es el lugar para estas tres líneas.',
      s:['Arco de personaje', 'Defecto trágico', 'Lo que está en juego', 'Dilema'] },
    { n:'Borrador cero', a:'Primer borrador rápido',
      d:'Escribir la historia de principio a fin lo más deprisa posible, sin releer ni corregir, solo para descubrir qué es. Anne Lamott lo llamó el primer borrador «de mierda» al que todo escritor tiene derecho; Terry Pratchett decía que el primer borrador es el autor contándose la historia a sí mismo.',
      u:'Fije una meta diaria, no vuelva atrás y deje marcas donde falte algo («[comprobar fecha]», «[aquí la escena de la pelea]»). El reto NaNoWriMo (50 000 palabras en un mes) se basa en esto.',
      c:'Un borrador cero no es un libro: es materia prima. El trabajo de verdad empieza en la revisión.',
      x:['Hábito corriente: escribir «XXX» en lugar de la palabra o el dato que falta y seguir adelante.'],
      s:['Planificar o descubrir', 'Revisión por capas'] },
    { n:'Revisión por capas', a:'Esquema inverso · reescritura por pasadas',
      d:'Revisar en varias pasadas, cada una con un solo objetivo, de lo mayor a lo menor: primero la estructura (orden, cortes, huecos), después las escenas (objetivo, conflicto, giro), los personajes (coherencia, voz) y solo al final la frase (ritmo, repeticiones, ortografía). El esquema inverso consiste en hacer la escaleta de lo que realmente está escrito, para ver la forma real del libro.',
      u:'Deje reposar el texto unas semanas. Haga el esquema inverso y compárelo con el plan. No pula frases de escenas que quizá acaben cortadas. Lea en voz alta en la última pasada.',
      c:'Corregir comas en la primera revisión es la trampa más común: da sensación de trabajo y no toca los problemas grandes.',
      x:['Preguntas de la primera pasada: ¿empieza la historia en el sitio justo? ¿Cada escena cambia algo? ¿Se cosecha lo sembrado? ¿Hay personajes que puedan fundirse en uno?', 'Preguntas de la última: ¿hay palabras repetidas en la misma página? ¿Empiezan todas las frases igual? ¿Están bien puntuados los diálogos con raya?'],
      t:'Reconstruir el libro escrito en el tablero (Escena a Escena, con POV y Arco narrativo) es un esquema inverso: los desequilibrios saltan a la vista (un hilo que desaparece durante diez Capítulos, un Personaje que no vuelve).',
      s:['Escaleta', 'Borrador cero', 'Siembra y cosecha', 'Entrar tarde, salir pronto'] },
    { n:'Los cinco mandamientos de la escena', a:'Story Grid (Shawn Coyne)',
      d:'Según este método de análisis, toda unidad narrativa (escena, secuencia, acto, libro) tiene cinco elementos: incidente incitador; complicación progresiva que culmina en un punto de giro; crisis (una elección difícil); clímax (la elección tomada); resolución.',
      u:'Lista de comprobación para las escenas que «no funcionan»: casi siempre falta la crisis, porque el personaje no tiene que elegir de verdad. El método pide además conocer el género y las escenas obligatorias que su lector espera.',
      c:'Aplicado mecánicamente a cada escena, produce un libro de crisis idénticas; algunas escenas son de respiro.',
      x:['Escenas obligatorias: el primer encuentro y la prueba de amor en una novela romántica; el hallazgo del cadáver y la revelación del culpable en una policiaca; el héroe a merced del villano en un thriller.'],
      s:['Escena y secuela', 'Dilema', 'Clímax', 'Incidente incitador'] },
    { n:'Biblia de la serie', a:'Dosier de continuidad · biblia del mundo',
      d:'El documento donde se registra todo lo que ya está fijado en el universo de la historia: fichas de personajes (edad, aspecto, tics, qué saben y desde cuándo), cronología, mapas, reglas del mundo, vocabulario, decisiones tomadas.',
      u:'Imprescindible en sagas, series e historias con muchos personajes: evita ojos que cambian de color y muertos que vuelven. Actualícela mientras escribe, no después.',
      c:'No la convierta en una enciclopedia que nunca consulta: debe ser rápida de buscar y estar al día.',
      t:'La herramienta es, en parte, eso mismo: fichas de Personajes y Escenarios, Arcos narrativos con sus dos órdenes, y Referencias y Notas asociadas a cada elemento, a lo largo de varios Tomos.',
      x:['La cronología y los apéndices de Tolkien.', 'Las tablas de J. K. Rowling con una columna por hilo narrativo.', 'Las «biblias» de las series de televisión, que los guionistas nuevos reciben al incorporarse.', 'Galdós, con sus personajes que reaparecen de una novela a otra a lo largo de los *Episodios nacionales* y las *Novelas contemporáneas*.'],
      s:['Construcción de mundos', 'Escaleta', 'Entrelazamiento'] },
    { n:'El tema como pregunta', a:'Argumento temático',
      d:'El tema es aquello de lo que trata la historia por debajo de la trama. Funciona mejor formulado como pregunta abierta («¿Hasta dónde se puede llegar por amor?») que como lección («El amor lo vence todo»).',
      u:'Ponga a los personajes a dar respuestas distintas a la misma pregunta (el protagonista, el antagonista, las subtramas) y deje que el clímax las ponga a prueba. A menudo el tema solo se descubre al final del primer borrador; se refuerza en la revisión, con motivos y ecos.',
      c:'Un personaje que enuncia la moraleja convierte la novela en sermón.',
      x:['*Don Quijote*: ¿dónde termina la locura y empieza la nobleza de soñar?', '*La Regenta*: ¿puede una mujer vivir de verdad en una ciudad que todo lo vigila?', '*Ensayo sobre la ceguera* (Saramago): ¿qué queda de la humanidad cuando nadie nos ve?', '*Frankenstein*: ¿qué le debe el creador a la criatura?'],
      s:['Motivo recurrente', 'Subtrama', 'Símbolo', 'Premisa y logline'] }
  ]}
]});

/* ============ ESTILOS NARRATIVOS ============
   Corrientes literarias, géneros narrativos y modos de escribir la prosa. Algunas estéticas ya tienen ficha en los
   Recursos estilísticos (realismo y naturalismo, gótico, novela negra como estilo, barroco...): aquí se enlazan sin repetirse. */
SUPPORT.push({ key:'estilos-narrativos', name:'Estilos narrativos', kicker:'Estilo narrativo',
  intro:'Las grandes maneras de contar una historia: las corrientes literarias (lo que una época entendió que debía ser una novela), los géneros narrativos (el tipo de libro y lo que el lector espera de él) y los modos de escribir la prosa. Conocerlos ayuda a elegir con intención y a mezclar con conocimiento de causa. Los ejemplos privilegian la literatura en español, de España y de América, sin olvidar los clásicos que todo escritor lee.',
  groups:[

  { name:'Corrientes y épocas', items:[
    { n:'Romanticismo', a:'Primera mitad del siglo XIX (en España, sobre todo de 1833 a 1850)',
      d:'Movimiento que puso en el centro de la literatura el sentimiento, la individualidad, la naturaleza, el pasado nacional y la libertad. En España triunfa tras la muerte de Fernando VII, con el regreso de los exiliados: Larra, Espronceda, el duque de Rivas, Zorrilla y, ya tardío, Bécquer. En América se une a la construcción de las nuevas naciones (Echeverría, Isaacs, Gómez de Avellaneda).',
      u:'Herencia útil hoy: personajes movidos por pasiones absolutas, conflictos entre el individuo y la sociedad (la familia, la honra, la clase), paisajes que reflejan el estado de ánimo, la fascinación por la Edad Media y las ruinas, el destino trágico. Funciona en la novela histórica, el drama pasional y cualquier historia de amor imposible.',
      c:'El exceso romántico (lágrimas, desmayos, coincidencias providenciales) ha envejecido mal; use la intensidad, no los amaneramientos. El personaje romántico necesita un mundo que le resista; si no, la pasión es solo ruido.',
      x:['Enrique Gil y Carrasco, *El señor de Bembibre* (1844), novela histórica.', 'Gustavo Adolfo Bécquer, *Leyendas* (1858-1864).', 'Jorge Isaacs, *María* (1867), Colombia.', 'Esteban Echeverría, «El matadero» (escrito hacia 1840), Argentina.'],
      s:['Realismo y naturalismo', 'Novela histórica', 'Gótico', 'Falacia patética'] },
    { n:'Modernismo hispánico', a:'De 1888 (*Azul...*, Rubén Darío) a la Primera Guerra Mundial',
      d:'Primer movimiento literario nacido en América que influye en España. Busca la belleza, la musicalidad y el refinamiento, con elementos del simbolismo y del parnasianismo franceses: exotismo, cosmopolitismo, culto a la forma, decadentismo. Ojo: no es lo mismo que el «modernismo» anglosajón (Joyce, Woolf), que en español solemos llamar vanguardias.',
      u:'Útil para la prosa de atmósfera y de sensaciones: frases rítmicas, color, sinestesias, escenarios decadentes y refinados. Valle-Inclán, en las *Sonatas*, muestra cómo hacer novela con una voz exquisita e irónica a la vez.',
      c:'Puede volverse ornamental y vacío: la sugestión solo funciona si hay algo concreto detrás del adorno.',
      x:['Rubén Darío, *Azul...* (1888), cuentos y poemas en prosa.', 'José Asunción Silva, *De sobremesa* (escrita hacia 1896, publicada en 1925), novela decadentista.', 'Valle-Inclán, *Sonatas* (1902-1905).', 'Huysmans, *A contrapelo* (1884), el breviario del decadentismo europeo.'],
      s:['Prosa poética', 'Símbolo', 'Atmósfera', 'Estilo lírico'] },
    { n:'Generación del 98', a:'España, cambio del siglo XIX al XX',
      d:'Grupo de escritores marcados por la crisis del «Desastre» de 1898 y la preocupación por España, el sentido de la vida y la fe: Unamuno, Baroja, Azorín, Valle-Inclán, Antonio Machado. En la novela rompen con el realismo decimonónico: más subjetividad, ideas, paisaje interiorizado y estructuras abiertas.',
      u:'Buen modelo para la novela de ideas y de conciencia: personajes divididos entre la voluntad y la abulia, la duda religiosa, la crisis del individuo frente a un país en decadencia. Baroja enseña a narrar con agilidad y frases cortas; Azorín, la minucia del detalle y del instante; Unamuno, la novela como agonía de la conciencia.',
      c:'La novela de ideas se convierte fácilmente en tertulia. Los mejores del 98 encarnan las ideas en personajes y conflictos concretos.',
      x:['Pío Baroja, *El árbol de la ciencia* (1911).', 'Miguel de Unamuno, *Niebla* (1914) y *San Manuel Bueno, mártir* (1931).', 'Azorín, *La voluntad* (1902).'],
      s:['Nivola', 'Novela psicológica', 'Existencialismo', 'Estilo ensayístico'] },
    { n:'Vanguardias y modernismo europeo', a:'Primeras décadas del siglo XX · modernism anglosajón',
      d:'Ruptura con las formas heredadas: fragmentación, múltiples puntos de vista, flujo de conciencia, tiempo subjetivo, experimentación con el lenguaje. En inglés se llama *modernism* (Joyce, Woolf, Faulkner); en España y América coincide con los ismos de vanguardia: ultraísmo, creacionismo, estridentismo, la prosa de Ramón Gómez de la Serna y la «novela deshumanizada» de los años veinte.',
      u:'Las vanguardias dieron a la novela las herramientas de la interioridad: el monólogo interior, el cambio de focalización, el tiempo psicológico en lugar del cronológico. Úselas cuando la historia está más en la cabeza de los personajes que en los hechos.',
      c:'Imitar la dificultad de las vanguardias sin su necesidad produce textos oscuros. Los grandes son difíciles porque lo que quieren decir no cabe en la forma tradicional.',
      x:['James Joyce, *Ulises* (1922); Virginia Woolf, *La señora Dalloway* (1925).', 'Ramón Gómez de la Serna, *El novelista* (1923) y sus greguerías.', 'Roberto Arlt, *Los siete locos* (1929), Argentina.', 'Macedonio Fernández, *Museo de la Novela de la Eterna* (publicada en 1967).'],
      s:['Flujo de conciencia', 'Monólogo interior', 'Narración no lineal', 'Surrealismo'] },
    { n:'Surrealismo', a:'Europa, desde 1924 · España y América en los años veinte y treinta',
      d:'Movimiento que busca liberar la imaginación del control de la razón: el sueño, el azar, el inconsciente, las asociaciones libres, el humor absurdo. En español se manifiesta sobre todo en la poesía (*Poeta en Nueva York*, de Lorca), en el cine de Buñuel y en pintores como Dalí, Maruja Mallo o Remedios Varo.',
      u:'En la narración, el surrealismo sirve para escenas de sueño, para la lógica onírica de un cuento, para imágenes inesperadas que revelan lo que el personaje no sabe que siente. El cuento breve es su formato natural.',
      c:'Lo insólito por lo insólito se agota pronto. Incluso un cuento surrealista necesita una lógica interna y un centro emocional.',
      x:['Luis Buñuel y Salvador Dalí, *Un perro andaluz* (1929), en cine.', 'Leonora Carrington, *La trompetilla acústica* (1974), escrita en México.', 'Felisberto Hernández, *Nadie encendía las lámparas* (1947), Uruguay, en la frontera de lo surreal.'],
      s:['Absurdo', 'Realismo mágico', 'Humor negro', 'Extrañamiento'] },
    { n:'Existencialismo', a:'Mediados del siglo XX',
      d:'Corriente filosófica y literaria centrada en la libertad, la angustia, el absurdo de la existencia y la responsabilidad de elegir sin garantías. En Francia, Sartre, Camus y Simone de Beauvoir; en español, con Unamuno como precursor, la novela de la inmediata posguerra española y el Río de la Plata.',
      u:'Ponga a un personaje ante una elección sin reglas exteriores que la resuelvan. La tensión viene de la conciencia: lo que el personaje sabe de sí mismo y del mundo, y lo que hace con eso. Funciona en narraciones desnudas, en primera persona y de tono reflexivo.',
      c:'El riesgo es el personaje tesis que diserta sobre el absurdo en lugar de vivirlo. La situación concreta (un crimen, una enfermedad, una casa asfixiante) tiene que cargar con la idea.',
      x:['Ernesto Sábato, *El túnel* (1948).', 'Juan Carlos Onetti, *El pozo* (1939).', 'Carmen Laforet, *Nada* (1945).', 'Albert Camus, *El extranjero* (1942).'],
      s:['Absurdo', 'Novela psicológica', 'Estilo ensayístico', 'Dilema'] },
    { n:'Tremendismo', a:'España, años cuarenta',
      d:'Tendencia de la novela española de la inmediata posguerra que presenta con crudeza la violencia, la miseria y la degradación física y moral, a menudo a través de personajes marginales. Arranca con *La familia de Pascual Duarte* (1942), de Camilo José Cela.',
      u:'Útil para narradores brutales y para mundos donde la violencia es cotidiana. La lección de Cela: la crudeza impresiona más contada con calma, por una voz que no se escandaliza de lo que cuenta.',
      c:'Acumular horrores insensibiliza al lector. La violencia necesita un personaje que la haga comprensible y una sociedad que la explique.',
      x:['Camilo José Cela, *La familia de Pascual Duarte* (1942): las memorias de un campesino condenado a muerte.', 'Carmen Laforet, *Nada* (1945), con elementos tremendistas en la casa de la calle de Aribau.'],
      s:['Realismo y naturalismo', 'Narrador no fiable', 'Antihéroe', 'Realismo social'] },
    { n:'Realismo social', a:'España, años cincuenta · objetivismo · generación del medio siglo',
      d:'Novela que retrata la sociedad de la posguerra (obreros, campesinos, la burguesía ociosa, la vida gris de la ciudad) con intención crítica y, a menudo, con técnica objetivista: narrador como cámara, mucho diálogo, poco comentario. En América tiene un paralelo en la novela indigenista y social (Ciro Alegría, José María Arguedas).',
      u:'Útil para historias en las que el protagonista es un grupo, una clase o una comunidad, y en las que el medio decide el destino. Enseña a documentarse, a escuchar cómo habla la gente y a dejar que los hechos hablen sin subrayados.',
      c:'La tesis ideológica a la vista convierte a los personajes en símbolos y la novela en panfleto; el objetivismo extremo, en acta notarial. Los mejores, como Sánchez Ferlosio o Martín Gaite, cuentan la injusticia a través de personas concretas.',
      x:['Rafael Sánchez Ferlosio, *El Jarama* (1956): un domingo de excursión a orillas del río.', 'Carmen Martín Gaite, *Entre visillos* (1958).', 'Ignacio Aldecoa, *Gran Sol* (1957).', 'José María Arguedas, *Los ríos profundos* (1958), Perú.'],
      s:['Novela coral', 'Novela de costumbres', 'Estilo cinematográfico', 'Realismo y naturalismo'] },
    { n:'Nouveau roman y novela experimental', a:'*Nouveau roman* (Francia, años cincuenta y sesenta) · renovación española de los sesenta',
      d:'El *nouveau roman* francés (Robbe-Grillet, Nathalie Sarraute, Michel Butor, Claude Simon) rechazó el personaje psicológico y la trama tradicional: descripciones minuciosas y objetivas, repeticiones, tiempo desordenado, el lector reconstruyendo la historia. En España, *Tiempo de silencio* (1962) abre una década de experimentación que rompe con el realismo social.',
      u:'Útil como laboratorio: la descripción «objetiva» que revela una obsesión, la repetición de una escena con pequeñas variaciones, la novela en segunda persona (*La modificación*, de Butor; *Señas de identidad*, de Goytisolo, en parte). Hoy se usa sobre todo por partes, como técnica.',
      c:'En una novela entera exige mucho del lector. La experimentación debe responder a lo que se cuenta, no a una moda.',
      x:['Alain Robbe-Grillet, *La celosía* (1957).', 'Luis Martín-Santos, *Tiempo de silencio* (1962).', 'Juan Goytisolo, *Señas de identidad* (1966); Juan Benet, *Volverás a Región* (1967).', 'Miguel Delibes, *Cinco horas con Mario* (1966).'],
      s:["Narrador en segunda persona", 'Extrañamiento', 'Escritura con restricciones', 'Monólogo interior'] },
    { n:'Boom latinoamericano', a:'Años sesenta y setenta',
      d:'La explosión internacional de la novela hispanoamericana: Cortázar, García Márquez, Vargas Llosa y Carlos Fuentes, con precursores como Borges, Rulfo, Carpentier y Onetti, y una editorial barcelonesa (Seix Barral) y una agente (Carmen Balcells) como plataforma. Une la ambición formal de las vanguardias a la historia, el mito y la política de América.',
      u:'Su lección para el novelista: la técnica al servicio de un mundo. Estructuras complejas (tiempos cruzados, varias voces, segunda persona, montaje) para contar una sociedad entera; el realismo mágico como manera de decir lo real; la ambición de la novela total.',
      c:'Imitar sus marcas visibles (el pueblo mítico, la saga familiar, el prodigio cotidiano) sin su necesidad produce pastiches. Hasta sus autores huyeron pronto de la etiqueta.',
      x:['Julio Cortázar, *Rayuela* (1963).', 'Mario Vargas Llosa, *La ciudad y los perros* (1963) y *Conversación en La Catedral* (1969).', 'Carlos Fuentes, *La muerte de Artemio Cruz* (1962).', 'Gabriel García Márquez, *Cien años de soledad* (1967).'],
      s:['Realismo mágico', 'Montaje paralelo', 'Narración no lineal', 'Novela del dictador'] },
    { n:'Posmodernismo', a:'Desde los años sesenta y setenta · en España, desde la Transición',
      d:'Ficción que juega consigo misma: metaficción, parodia, intertextualidad, mezcla de géneros y de registros, desconfianza de los grandes relatos, reescritura irónica de la historia. En España suele datarse su arranque en *La verdad sobre el caso Savolta* (1975), de Eduardo Mendoza, que vuelve a contar una historia sin renunciar al juego.',
      u:'Úselo para reescribir la Historia desde los márgenes (quién no aparece en los libros), para narradores que comentan la propia narración, para collages de documentos y voces, para mezclar el género policiaco con la erudición.',
      c:'La ironía y la autorreferencia en exceso alejan al lector de la historia. Las grandes novelas posmodernas son, antes que nada, buenas historias.',
      x:['Eduardo Mendoza, *La verdad sobre el caso Savolta* (1975).', 'Ricardo Piglia, *Respiración artificial* (1980).', 'Enrique Vila-Matas, *Bartleby y compañía* (2000).', 'Umberto Eco, *El nombre de la rosa* (1980); Italo Calvino, *Si una noche de invierno un viajero* (1979).'],
      s:['Metaficción', 'Intertextualidad', 'Pastiche y parodia', 'Novela histórica', 'Narrador intruso'] },
    { n:'Minimalismo y realismo sucio', a:'Hemingway, Carver · dirty realism',
      d:'Prosa depurada hasta lo esencial: frases cortas, vocabulario sencillo, poca adjetivación, diálogos secos, casi ninguna explicación psicológica. El sentido está en lo que no se dice. Viene de Hemingway y su teoría del iceberg y tiene en Raymond Carver el modelo del cuento. El «realismo sucio» le añade ambientes marginales y vidas a la deriva.',
      u:'Excelente para cuentos y para historias de vidas corrientes, con emoción contenida. Corte todo lo que el lector puede deducir; deje que hablen los gestos y los silencios.',
      c:'Mal hecho, es solo pobreza de lenguaje y escenas sin tensión. El minimalismo exige un subtexto fuerte; sin él, no hay nada bajo la superficie.',
      x:['Raymond Carver, *De qué hablamos cuando hablamos de amor* (1981).', 'Ernest Hemingway, «Colinas como elefantes blancos» (1927).', 'Pedro Juan Gutiérrez, *Trilogía sucia de La Habana* (1998).', 'Juan Rulfo, *El llano en llamas* (1953), mucho antes de la etiqueta: concisión extrema.'],
      s:['Teoría del iceberg', 'Subtexto', "Frase breve", 'Maximalismo', 'Estilo sobrio'] },
    { n:'Autoficción', a:'Novela autobiográfica · relato real · desde los años setenta',
      d:'Narración en la que el autor se pone como personaje, con su nombre o uno cercano, mezclando hechos de su vida e invención. El término es de Serge Doubrovsky (1977). En español ha dado algunos de los libros más leídos de las últimas décadas, a veces bajo el nombre de «relato real».',
      u:'Da a la ficción la fuerza del testimonio. Funciona cuando el «yo» se trata como un personaje (con defectos, ángulos muertos y un recorrido) y no como un diario.',
      c:'Cuestiones éticas y legales con personas reales reconocibles. Y el riesgo del ombligo: la vida del autor solo interesa al lector si se convierte en historia.',
      x:['Javier Cercas, *Soldados de Salamina* (2001): un narrador llamado Javier Cercas investiga un fusilamiento de la guerra civil.', 'Rosa Montero, *La loca de la casa* (2003).', 'Fernando Vallejo, *La virgen de los sicarios* (1994), Colombia.', 'Karl Ove Knausgård, *Mi lucha* (2009-2011).'],
      s:['Narrador no fiable', 'Metaficción', 'Estilo periodístico'] }
  ]},

  { name:'Géneros narrativos', items:[
    { n:'Novela', a:'La narración larga',
      d:'Narración extensa en prosa, con varios personajes, acciones y espacios, que puede abarcar una vida, una familia o una época. Es el género más flexible: absorbe a todos los demás. La novela moderna nace en buena parte en español, con el *Quijote* (1605-1615).',
      u:'Pide una pregunta que aguante cientos de páginas y un desarrollo de los personajes. Use las fichas de estructura (tres actos, viaje del héroe, Story Circle) para diseñarla y la herramienta para seguir Tomos, Capítulos, Escenas y Arcos narrativos.',
      c:'Una novela no es un cuento estirado: necesita subtramas, variación de ritmo y personajes que cambian. Ojo con el falso amigo: en inglés *novel* es novela, pero *novella* es novela corta, y una telenovela no es una novela.',
      x:['Miguel de Cervantes, *Don Quijote de la Mancha* (1605-1615).', 'Benito Pérez Galdós, *Fortunata y Jacinta* (1887).', 'Gabriel García Márquez, *Cien años de soledad* (1967).', 'Roberto Bolaño, *2666* (2004).'],
      t:'Cada Tomo de la herramienta puede ser una novela de una serie, o una parte de una novela larga.',
      s:['Novela corta', 'Cuento', 'Estructura en tres actos', 'Subtrama'] },
    { n:'Novela corta', a:'Nouvelle · novella · narración de extensión media',
      d:'Narración de extensión intermedia entre el cuento y la novela: una acción principal, pocos personajes, un tiempo concentrado, pero más desarrollo que el cuento. En el Siglo de Oro, «novela» significaba precisamente esto (a la italiana): las *Novelas ejemplares* de Cervantes son relatos breves.',
      u:'Buen formato para una sola crisis vivida en profundidad, para una voz fuerte, para historias que perderían fuerza si se alargaran.',
      c:'No le añada subtramas para «llegar a novela»: la concentración es su virtud.',
      x:['Gabriel García Márquez, *El coronel no tiene quien le escriba* (1961) y *Crónica de una muerte anunciada* (1981).', 'Miguel de Unamuno, *San Manuel Bueno, mártir* (1931).', 'Tolstói, *La muerte de Iván Ilich* (1886); Hemingway, *El viejo y el mar* (1952).'],
      s:['Novela', 'Cuento'] },
    { n:'Cuento', a:'La narración breve · relato',
      d:'Narración corta, centrada en un momento, una situación o una revelación, con pocos personajes y economía de medios. Se lee de una sentada, y por eso lo apuesta todo a un efecto (Poe). La literatura en español tiene una de las grandes tradiciones del género, sobre todo en el Río de la Plata y en México.',
      u:'Empiece tarde, acabe pronto; cada frase debe servir al efecto final. El cuento vive a menudo de un cambio mínimo: alguien comprende algo o deja de poder ignorarlo (la «epifanía» de Joyce). Lea el decálogo de Quiroga y las tesis de Piglia.',
      c:'Un cuento no es el primer capítulo de una novela. Si la historia necesita más espacio, es otra cosa.',
      x:['Horacio Quiroga, *Cuentos de amor de locura y de muerte* (1917).', 'Jorge Luis Borges, *Ficciones* (1944); Julio Cortázar, *Bestiario* (1951).', 'Juan Rulfo, *El llano en llamas* (1953).', 'Leopoldo Alas, Clarín, «¡Adiós, Cordera!» (1892); Chéjov, «La dama del perrito» (1899).'],
      s:['Novela corta', 'Microrrelato', 'Decálogo del perfecto cuentista', 'Las dos historias del cuento', 'Última frase'] },
    { n:'Microrrelato', a:'Minificción · microcuento · relato hiperbreve',
      d:'Narración brevísima (de una línea a una página) que cuenta una historia completa apoyándose en la elipsis, la sorpresa y lo que el lector sabe o imagina. Es un género en el que el español ha sido pionero y sigue siendo central, de Julio Torri y Juan José Arreola a Ana María Shua.',
      u:'Elija un título que trabaje (puede dar el contexto que falta), arranque en mitad de la acción y deje que la última palabra cambie el sentido de todo. Apóyese en un referente compartido (un mito, un cuento, un dicho) para contar mucho con poco.',
      c:'No es un chiste ni un aforismo: tiene que haber una historia, con algo que cambia. Y no es un fragmento de algo más largo: tiene que sostenerse solo.',
      x:['Augusto Monterroso, «El dinosaurio» (1959): «Cuando despertó, el dinosaurio todavía estaba allí».', 'Juan José Arreola, *Confabulario* (1952).', 'Max Aub, *Crímenes ejemplares* (1957).', 'Ana María Shua, *La sueñera* (1984).'],
      s:['Cuento', 'Elipsis narrativa', 'Escritura con restricciones', 'Última frase'] },
    { n:'Crónica', a:'Crónica literaria · artículo de costumbres · columna',
      d:'Texto breve, publicado sobre todo en la prensa, que parte de la vida diaria (un episodio, una observación, un recuerdo) para llegar a una reflexión, a menudo con humor o lirismo. En español tiene una tradición riquísima: las crónicas de Indias, los artículos de costumbres de Larra y Mesonero Romanos, la crónica modernista (Martí, Darío) y la crónica latinoamericana actual, que se acerca al periodismo narrativo.',
      u:'La crónica entrena la voz: tono personal, ritmo, observación del detalle. Muchos novelistas son también cronistas o columnistas. En una novela, una voz de cronista da narradores cercanos, conversadores, irónicos.',
      c:'En una novela, el tono de crónica puede dispersar la narración en digresiones; úselo como color, no como estructura.',
      x:['Mariano José de Larra, «Vuelva usted mañana» (1833).', 'Bernal Díaz del Castillo, *Historia verdadera de la conquista de la Nueva España* (escrita en el siglo XVI).', 'Carlos Monsiváis, *Días de guardar* (1970), México.', 'Leila Guerriero, *Frutos extraños* (2009), Argentina.'],
      s:['Narrador intruso', 'Tono', 'Estilo periodístico', 'Novela de costumbres'] },
    { n:'Novela de formación', a:'*Bildungsroman* · novela de aprendizaje',
      d:'Novela que sigue la formación de un personaje, normalmente de la infancia o la juventud a la edad adulta, a través de experiencias, errores, pérdidas y descubrimientos.',
      u:'El arco del personaje es la propia trama. Elija bien las etapas (la salida de casa, el primer amor, la pérdida, el desengaño) y lo que el personaje aprende en cada una.',
      c:'La suma de episodios no hace una formación: cada etapa debe cambiar al personaje, y el final debe mostrar en quién se ha convertido.',
      x:['Goethe, *Los años de aprendizaje de Wilhelm Meister* (1795-1796); Dickens, *Grandes esperanzas* (1861).', 'Ricardo Güiraldes, *Don Segundo Sombra* (1926), Argentina.', 'Carmen Laforet, *Nada* (1945); Ana María Matute, *Primera memoria* (1960).', 'Mario Vargas Llosa, *La ciudad y los perros* (1963).'],
      s:['Arco de personaje', 'El viaje del héroe', 'Deseo y necesidad'] },
    { n:'Novela histórica', a:'Ficción en un tiempo pasado documentado',
      d:'Novela situada en una época histórica reconstruida, en la que personajes inventados conviven con hechos y, a veces, figuras reales. Nace con Walter Scott; en España la consagra Galdós con los *Episodios nacionales* (1872-1912), que cuentan el siglo XIX desde Trafalgar.',
      u:'Documéntese a fondo (costumbres, objetos, lengua, precios, distancias) y luego esconda la investigación dentro de las escenas. Elija un ángulo que la historia oficial no mostró. Para la lengua, consulte la sección de español antiguo.',
      c:'Los anacronismos de mentalidad son más graves que los de objetos: personajes con valores de hoy en una época que no los tenía. El exceso de información histórica frena la narración.',
      x:['Benito Pérez Galdós, *Trafalgar* (1873), primer *Episodio nacional*.', 'Alejo Carpentier, *El siglo de las luces* (1962).', 'Miguel Delibes, *El hereje* (1998); Arturo Pérez-Reverte, *El capitán Alatriste* (1996).', 'Marguerite Yourcenar, *Memorias de Adriano* (1951); Hilary Mantel, *En la corte del lobo* (2009).'],
      s:["Qué ortografía usar en cada época", 'Construcción de mundos', 'Arcaísmo', 'Posmodernismo'] },
    { n:'Novela policiaca', a:'Policial (en América) · novela de detectives · novela negra · *whodunit*',
      d:'Narración organizada en torno a un crimen y su investigación. La policiaca clásica o de enigma pide al lector que descubra al culpable; la novela negra se interesa por la violencia, la ciudad y la corrupción.',
      u:'Planifique el crimen del final hacia el principio: qué pasó, quién lo sabía, qué pistas quedaron. Reparta pistas verdaderas y falsas con lealtad (el lector debe poder adivinar). Los Arcos narrativos de la herramienta ayudan a separar la cronología del crimen del orden de la investigación.',
      c:'La solución tiene que estar preparada en el texto; un culpable que aparece al final sin pistas es trampa. Los detectives sin defectos no interesan.',
      x:['Edgar Allan Poe, «Los crímenes de la calle Morgue» (1841).', 'Emilia Pardo Bazán, *La gota de sangre* (1911), a menudo considerada la primera novela policiaca española.', 'Borges y Bioy Casares, *Seis problemas para don Isidro Parodi* (1942).', 'Manuel Vázquez Montalbán, *Los mares del Sur* (1979), con el detective Pepe Carvalho; Agatha Christie, *Asesinato en el Orient Express* (1934).'],
      t:'Use un Arco narrativo para la cronología real del crimen y otro para la investigación: el orden cronológico y el orden narrativo muestran lo que el lector sabe en cada momento.',
      s:["Estilo negro", 'Pista falsa', 'Siembra y cosecha', 'Suspense y sorpresa', 'Pregunta dramática'] },
    { n:'Lo fantástico', a:'Fantástico, maravilloso y extraño (Todorov)',
      d:'Narración en la que lo sobrenatural o lo imposible irrumpe en un mundo reconocible. Tzvetan Todorov (*Introducción a la literatura fantástica*, 1970) distinguió lo fantástico (la vacilación entre explicación natural y sobrenatural), lo extraño (todo se explica) y lo maravilloso (lo sobrenatural se acepta sin asombro, como en los cuentos de hadas y la fantasía). El Río de la Plata ha dado una de sus tradiciones más ricas.',
      u:'Decida el régimen de su libro: ¿el lector debe vacilar (fantástico), aceptar reglas nuevas (maravilloso, fantasía épica) o tener una explicación al final (extraño)? Las reglas de lo imposible, una vez establecidas, no se rompen.',
      c:'La magia sin límites quita la tensión: si todo es posible, nada está en juego. La explicación final apresurada deshace el efecto fantástico.',
      x:['Gustavo Adolfo Bécquer, «El monte de las ánimas» (1861).', 'Julio Cortázar, «Casa tomada» (1946); Adolfo Bioy Casares, *La invención de Morel* (1940).', 'Samanta Schweblin, *Distancia de rescate* (2014); Mariana Enriquez, *Las cosas que perdimos en el fuego* (2016).', 'Franz Kafka, *La metamorfosis* (1915); J. R. R. Tolkien, *El señor de los anillos* (1954-1955), fantasía.'],
      s:['Realismo mágico', 'Construcción de mundos', 'Gótico', 'Verosimilitud', 'El doble'] },
    { n:'Ciencia ficción y distopía', a:'Ficción especulativa · anticipación',
      d:'Narraciones que parten de una hipótesis científica, tecnológica o social para imaginar otro mundo, a menudo futuro. La distopía imagina una sociedad opresiva que exagera tendencias del presente; la utopía, una sociedad ideal.',
      u:'Parta de una pregunta «¿y si...?» y siga las consecuencias con rigor: economía, política, lengua, vida doméstica. La mejor ciencia ficción habla del presente a través del futuro.',
      c:'Exponer el mundo en bloques («como sabes, desde la Gran Guerra...») es el defecto más común. Muestre el mundo a través de los personajes.',
      x:['Enrique Gaspar, *El anacronópete* (1887), una máquina del tiempo anterior a la de Wells.', 'H. G. Wells, *La máquina del tiempo* (1895).', 'George Orwell, *1984* (1949); Aldous Huxley, *Un mundo feliz* (1932); Ursula K. Le Guin, *Los desposeídos* (1974).', 'Tomás Salvador, *La nave* (1959); José Saramago, *Ensayo sobre la ceguera* (1995), alegoría distópica.'],
      s:['Construcción de mundos', 'Exposición dosificada', 'Extrañamiento'] },
    { n:'Novela de costumbres', a:'Costumbrismo · retrato de una sociedad',
      d:'Novela que retrata los hábitos, valores, hipocresías y conflictos de un medio social (una ciudad, una clase, una época), a menudo con ironía. En España nace del costumbrismo romántico (los cuadros de costumbres de Larra y Mesonero Romanos, *La gaviota* de Fernán Caballero) y culmina en la gran novela realista de Galdós y Clarín.',
      u:'El medio es un personaje: fiestas, cenas, tertulias, rituales. La ironía del narrador revela la distancia entre lo que los personajes dicen y lo que hacen.',
      c:'La sátira de las costumbres envejece con ellas; lo que queda son los personajes. No deje que el retrato social se trague la historia. El costumbrismo puro (cuadros pintorescos sin conflicto) no es novela.',
      x:['Leopoldo Alas, Clarín, *La Regenta* (1884-1885).', 'Benito Pérez Galdós, *Fortunata y Jacinta* (1887).', 'Fernán Caballero, *La gaviota* (1849).', 'Jane Austen, *Orgullo y prejuicio* (1813).'],
      s:['Sátira', 'Ironía', 'Realismo y naturalismo', 'Estilo irónico'] },
    { n:'Novela psicológica', a:'Novela de introspección',
      d:'Novela centrada en la vida interior de los personajes (motivaciones, conflictos, recuerdos, conciencia) más que en la acción exterior.',
      u:'Focalización cercana, monólogo interior, estilo indirecto libre, analepsis de memoria. La acción puede ser mínima; la tensión nace de la contradicción entre lo que el personaje siente, piensa y hace.',
      c:'Sin un conflicto concreto que le obligue a elegir, la introspección se vuelve rumia. Dele un acontecimiento que lo ponga a prueba.',
      x:['Dostoievski, *Crimen y castigo* (1866).', 'Miguel de Unamuno, *Abel Sánchez* (1917).', 'Ernesto Sábato, *El túnel* (1948).', 'Miguel Delibes, *Cinco horas con Mario* (1966).'],
      s:['Monólogo interior', 'Estilo indirecto libre', 'Existencialismo', 'Generación del 98'] },
    { n:'Novela picaresca', a:'El antihéroe que sobrevive de expedientes · género nacido en España',
      d:'Narración, por lo general en primera persona, de un pícaro (un marginal astuto que pasa por varios amos y lugares) que muestra con humor y crueldad la sociedad de abajo arriba. Es un género español del Siglo de Oro que se extendió por toda Europa.',
      u:'Estructura episódica (cada amo, cada ciudad, un episodio) y una voz cínica y divertida que justifica su vida ante un destinatario. Buena para la sátira social y para narradores poco fiables.',
      c:'Los episodios sueltos necesitan un hilo: un cambio en el narrador o una pregunta que atraviese el libro (en el *Lazarillo*, el «caso» que Lázaro explica a «Vuestra Merced»).',
      x:['*Lazarillo de Tormes* (1554), anónimo.', 'Mateo Alemán, *Guzmán de Alfarache* (1599-1604); Francisco de Quevedo, *El Buscón* (1626).', 'José Joaquín Fernández de Lizardi, *El Periquillo Sarniento* (1816), México.', 'Eduardo Mendoza, *El misterio de la cripta embrujada* (1979), que lo parodia con un detective pícaro.'],
      s:['Antihéroe', 'Narrador no fiable', 'Sátira', 'Novela fragmentaria'] },
    { n:'Literatura de viajes', a:'Relato de viaje · novela de viaje',
      d:'Narraciones organizadas en torno a un desplazamiento, real o inventado, en las que el viaje exterior acompaña una transformación interior. En español va de las relaciones medievales y de Indias al libro de viaje del siglo XX.',
      u:'La estructura viene del itinerario; el interés, de la mirada. Alterne paisaje, encuentros y reflexión. El camino o el mar dan un ritmo natural de episodios.',
      c:'El catálogo de lugares no hace una narración: necesita una pregunta y un viajero que cambie.',
      x:['Ruy González de Clavijo, *Embajada a Tamorlán* (siglo XV).', 'Álvar Núñez Cabeza de Vaca, *Naufragios* (1542).', 'Camilo José Cela, *Viaje a la Alcarria* (1948).', 'Jack Kerouac, *En el camino* (1957).'],
      s:['El viaje del héroe', 'Novela de formación', 'Relato enmarcado'] },
    { n:'Libros de caballerías', a:'Novela de caballerías · materia artúrica',
      d:'Narraciones medievales y renacentistas de caballeros, pruebas, amores corteses y maravillas. En la península triunfan con el *Amadís de Gaula* (versión de Garci Rodríguez de Montalvo, 1508) y sus continuaciones, y con el *Tirant lo Blanch* valenciano (1490). El *Quijote* nace como su parodia.',
      u:'Fuente para la fantasía, la novela histórica medieval y la parodia. La estructura de búsqueda (una demanda con pruebas sucesivas) y el entrelazamiento de aventuras siguen organizando muchas tramas.',
      c:'Los valores del género (honra, linaje, castidad) no son los de hoy: úselos con conciencia, o para cuestionarlos.',
      x:['*Amadís de Gaula* (1508).', 'Joanot Martorell, *Tirant lo Blanch* (1490), elogiado en el escrutinio de la biblioteca de don Quijote.', '*Las sergas de Esplandián* (1510), de donde viene el nombre de California.', 'Miguel de Cervantes, *Don Quijote de la Mancha* (1605-1615), que los parodia y los supera.'],
      s:['El viaje del héroe', 'Lo fantástico', 'Entrelazamiento'] },
    { n:'Cuento tradicional y fábula', a:'Cuento popular · cuento de hadas · fábula · leyenda · apólogo',
      d:'Narraciones de transmisión oral, recogidas y fijadas por escrito: cuentos maravillosos, cuentos de animales, leyendas locales, fábulas con moraleja. En castellano, la tradición escrita empieza con los apólogos orientales (*Calila e Dimna*, 1251) y *El conde Lucanor*; en el siglo XX, Aurelio M. Espinosa recogió los *Cuentos populares españoles* (1923-1926).',
      u:'Estructuras sencillas y fuertes (tres pruebas, la prohibición transgredida, el hermano menor), personajes tipo y un ritmo de repetición. Para reescribirlas, adaptarlas al presente o usarlas como esqueleto de una novela.',
      c:'La moraleja explícita al final, en una narración para adultos, suena a sermón. Las versiones recogidas en el siglo XIX son a menudo crueles y extrañas: ahí está su fuerza.',
      x:['Don Juan Manuel, *El conde Lucanor* (1335).', 'Félix María Samaniego, *Fábulas morales* (1781); Tomás de Iriarte, *Fábulas literarias* (1782).', 'Ricardo Palma, *Tradiciones peruanas* (desde 1872).', 'Esopo; La Fontaine; los hermanos Grimm, *Cuentos de la infancia y del hogar* (1812).'],
      s:['Personaje tipo', 'Regla de tres', 'Morfología del cuento', 'Alegoría'] },
    { n:'Novela del dictador', a:'Género hispanoamericano del siglo XX',
      d:'Novela que tiene como centro la figura de un dictador (real, inventado o compuesto) y el sistema de poder que lo rodea. Es un género casi propio de la literatura hispanoamericana, inaugurado por Valle-Inclán con *Tirano Banderas* (1926).',
      u:'El reto es narrar el poder absoluto sin caer en el panfleto: desde dentro de la cabeza del tirano, desde sus víctimas o desde los cortesanos. La polifonía, el monólogo y el esperpento son herramientas habituales.',
      c:'El dictador de cartón piedra, malo de caricatura, no da miedo ni explica nada. El horror más eficaz es el cotidiano: la burocracia, el miedo, la complicidad.',
      x:['Ramón del Valle-Inclán, *Tirano Banderas* (1926).', 'Miguel Ángel Asturias, *El señor presidente* (1946).', 'Augusto Roa Bastos, *Yo el Supremo* (1974); Alejo Carpentier, *El recurso del método* (1974); García Márquez, *El otoño del patriarca* (1975).', 'Mario Vargas Llosa, *La fiesta del Chivo* (2000).'],
      s:['Boom latinoamericano', 'Antagonista', 'Novela histórica', 'Sátira'] },
    { n:'Nivola', a:'Término de Unamuno (*Niebla*, 1914)',
      d:'Nombre que Miguel de Unamuno inventó para *Niebla*, para escapar de las reglas de la «novela» realista: poca descripción, mucho diálogo y monólogo, personajes que son conciencias en conflicto, y un autor que entra en la historia y discute con su criatura.',
      u:'Modelo para la novela de ideas y para la metaficción: haga que el personaje dude de su propia existencia, que el diálogo lleve la acción y que la forma se discuta dentro del libro. Para Unamuno, la «nivola» era la libertad de inventar la propia forma.',
      c:'Sin un conflicto vital (en *Niebla*, el amor de Augusto y la pregunta de si existe), la nivola se queda en charla filosófica.',
      x:['Miguel de Unamuno, *Niebla* (1914): Augusto Pérez visita a Unamuno en Salamanca para discutir su muerte.', 'El prólogo de *Niebla*, firmado por un personaje, Víctor Goti, y el «post-prólogo» del propio Unamuno.'],
      s:['Metaficción', 'Metalepsis', 'Generación del 98'] }
  ]},

  { name:'Modos de escribir la prosa', items:[
    { n:'Estilo sobrio', a:'Prosa clásica · transparencia',
      d:'Prosa clara, precisa y discreta, que no llama la atención sobre sí misma: el lector ve la historia a través de ella, como a través de una ventana limpia.',
      u:'Frases bien construidas, vocabulario exacto, adjetivos elegidos uno a uno, metáforas escasas y certeras. Es el registro más versátil y el que mejor envejece.',
      c:'Sobrio no es pobre ni neutro: la precisión exige trabajo. Sin ninguna imagen fuerte, el texto se vuelve gris.',
      x:['Chéjov, en los cuentos; J. M. Coetzee, *Desgracia* (1999).', 'Miguel Delibes, *El camino* (1950).', 'Antonio Muñoz Molina, *Plenilunio* (1997).'],
      s:['Minimalismo y realismo sucio', 'Elección léxica', 'Estilo lírico'] },
    { n:'Estilo lírico', a:'Prosa poética en la narración',
      d:'Prosa que se acerca a la poesía: ritmo marcado, imágenes, repeticiones, musicalidad, atención a las sensaciones y a los estados de ánimo.',
      u:'Bueno para la memoria, el paisaje, la infancia, la pérdida, y para narradores sensibles al mundo. Altérnelo con pasajes más sobrios para que el lirismo no pierda efecto.',
      c:'Una novela entera en registro lírico cansa y puede ahogar la acción. La emoción debe nacer de las imágenes, no de los adjetivos.',
      x:['Juan Ramón Jiménez, *Platero y yo* (1914).', 'Juan Rulfo, *Pedro Páramo* (1955).', 'Julio Llamazares, *La lluvia amarilla* (1988).'],
      s:['Prosa poética', 'Ritmo de la frase', 'Imágenes sensoriales', 'Modernismo hispánico'] },
    { n:'Estilo telegráfico', a:'Frases nominales · elipsis',
      d:'Prosa hecha de frases muy cortas, a menudo sin verbo, con elipsis de artículos y conectores. Imita la anotación, la urgencia, el pensamiento a fogonazos.',
      u:'Útil en escenas de tensión extrema, diarios, notas de personajes, el pensamiento de alguien en estado de choque. En pequeñas dosis, da velocidad.',
      c:'Páginas seguidas cansan y suenan a guion o a lista. Úselo como cambio de ritmo.',
      x:['«Sirena. Humo. Nadie en la escalera. El teléfono, otra vez».'],
      s:['Frase nominal', "Frase breve", "Elipsis (figura)", 'Asíndeton'] },
    { n:'Estilo cinematográfico', a:'Escribir por planos · objetivismo',
      d:'Prosa que imita a la cámara: describe lo que se ve y se oye, por planos (general, medio, detalle), con cortes secos entre escenas, pocos comentarios y a menudo en presente.',
      u:'Muy eficaz en la acción y el suspense. Piense en planos: abra con el general, acérquese al detalle revelador, corte. La herramienta, con las Escenas en el tablero, ayuda a montar como en una mesa de montaje.',
      c:'Un libro no es una película: la prosa puede entrar en la cabeza de los personajes, cosa que la cámara no hace. Renunciar a eso es desperdiciar lo que solo tiene la novela.',
      x:['Camilo José Cela, *La colmena* (1951): el narrador recorre el café como una cámara.', 'Manuel Puig, *La traición de Rita Hayworth* (1968), novela empapada de cine.', 'Apertura por planos: «La playa vacía. Una toalla roja. Al lado, un zapato de niño».'],
      s:["Narrador objetivo (cámara)", 'Montaje paralelo', 'Mostrar, no contar', 'Entrar tarde, salir pronto', 'Realismo social'] },
    { n:'Estilo periodístico', a:'Periodismo narrativo · no ficción · novela de no ficción',
      d:'Prosa que usa las técnicas de la novela para contar hechos reales, o ficción que imita el reportaje (fechas, nombres, documentos, testimonios). *A sangre fría* (Capote, 1966) y el «nuevo periodismo» estadounidense son referencias, pero en español Rodolfo Walsh ya lo había hecho en *Operación masacre* (1957).',
      u:'Da verosimilitud y urgencia. En la ficción, el reportaje simulado (entrevistas, transcripciones, noticias) crea efectos de documental.',
      c:'En la no ficción, inventar es romper el pacto con el lector. En la ficción, el falso reportaje necesita una coherencia total en los detalles.',
      x:['Rodolfo Walsh, *Operación masacre* (1957).', 'Gabriel García Márquez, *Relato de un náufrago* (1955 en prensa, 1970 en libro) y *Noticia de un secuestro* (1996).', 'Elena Poniatowska, *La noche de Tlatelolco* (1971); Javier Cercas, *Anatomía de un instante* (2009).', 'Svetlana Alexiévich, *La guerra no tiene rostro de mujer* (1985).'],
      s:["Narración epistolar o documental", 'Verosimilitud', 'Detalle significativo', 'Crónica', 'Autoficción'] },
    { n:'Estilo ensayístico', a:'La novela que piensa',
      d:'Narración en la que el narrador (o el autor) interrumpe la historia para reflexionar sobre la vida, la sociedad o la propia escritura, y acerca la novela al ensayo.',
      u:'Funciona cuando la reflexión nace de la historia y la ilumina. Un narrador que piensa en voz alta puede ser el gran personaje del libro.',
      c:'Las digresiones frenan la trama: dosifíquelas y asegúrese de que cada una aporta algo que la escena no diría.',
      x:['Milan Kundera, *La insoportable levedad del ser* (1984).', 'Javier Marías, *Corazón tan blanco* (1992).', 'Miguel de Unamuno, *Niebla* (1914).', 'Ernesto Sábato, *Sobre héroes y tumbas* (1961), con el «Informe sobre ciegos».'],
      s:['Narrador intruso', 'Existencialismo', 'Metaficción', 'Pausa descriptiva'] },
    { n:'Estilo irónico', a:'Distancia y doble sentido',
      d:'Prosa en la que el narrador dice una cosa y deja entender otra: el elogio que es crítica, la seriedad que es burla. La ironía crea complicidad con el lector.',
      u:'La ironía vive de la distancia entre el tono y el contenido, entre lo que el personaje piensa de sí y lo que el lector ve. Cervantes, Clarín, Galdós y Machado de Assis son maestros en las lenguas ibéricas; Eduardo Mendoza, entre los contemporáneos.',
      c:'La ironía constante vacía a los personajes e impide que al lector le importen. Sepa cuándo dejarla a un lado.',
      x:['Leopoldo Alas, Clarín, *La Regenta* (1884-1885): Vetusta contada con una sonrisa cruel.', 'Eduardo Mendoza, *Sin noticias de Gurb* (1991).', 'Machado de Assis, *Memorias póstumas de Blas Cubas* (1881).'],
      s:['Ironía', 'Sátira', 'Novela de costumbres', 'Narrador intruso'] }
  ]}
  ]});
